INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198319222', 'Boneco Funko Pop! Disney Vida Real K-Pop - Minnie', 'A Minnie Mouse entra na batida do K-Pop com muito charme e atitude! O Boneco Funko Pop! Minnie traz a estrela da Disney em uma versão super estilosa, com um look moderno inspirado no universo musical coreano. Com cerca de 10 centíemtros de altura, esse colecionável de vinil é perfeito para fãs da Minnie, do K-Pop e da cultura pop em geral. Cheia de personalidade, a Minnie K-Pop é um destaque na linha Mickey & Amigos e uma adição imperdível para sua coleção. Ideal para presentear ou colecionar, ela combina a doçura clássica da personagem com um toque fashion que vai encantar adultos e crianças.', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824gf-mfk31ejswhe1b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F19198319222', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
