INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29226207290', 'Pote Com Tampa Bambu Pote Vidro Hermético Redondo Marmita Potes De Vidro Hermético', 'DESCRIÇÃO O pote hermético deve ser adicionado à lista de acessórios que não podem faltar nesta parte importante da casa. Usado para armazenar e conservar bolachas, doces, torradas e cereais, ele tem alto poder de conservação e mantém os alimentos com o sabor e a textura originais. · Vidro Borosilicato; · Vai ao forno (sem tampa), micro-ondas (sem tampa) e freezer; · Anel de silicone removível; · Mantém os alimentos frescos por mais tempo; · Evita que o cheiro se espalhe; · Sem risco de vazamento; · Fácil de limpar e higienizar; · Super Resistente. Cor: Sortidos Material: Vidro Capacidades: 400ML / 620ML / 950ML / 1750ML CONTEM APENAS 1 UNIDADE. Pode ser usado em: Freezer Forno Micro-ondas Lava-louças Atenção: vídeo meramente ilustrativo.', 39.9, 22.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6e161w6fq0755', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F29226207290', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
