INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42930826947', 'Tela secundária USB-C TROFEO VISION Thermalright de 9,16 polegadas, monitor LCD HD magnético', 'Tela LCD IPS completa Thermalright TROFEO VISION LCD Tamanho da tela: 9,16 polegadas Resolução: 1920*480 Interface: USB Tipo-C DIMENSÕES: 251x68x17mm DESCRIÇÃO DO SOFTWARE A série de telas de controle de água TROFEO VISION LCD oferece monitoramento em tempo real, transmissão de dados, ativação, desativação e outras funções controladas por software. Baixe o software do site oficial: descompacte e clique duas vezes no instalador para instalar. Execute o software clicando duas vezes no ícone "TRCC" na área de trabalho. A alimentação da tela e a transmissão de dados são fornecidas pela interface USB de 9 pinos na placa-mãe; certifique-se de que a fiação esteja completa antes de instalar o software. Após a instalação, ele iniciará automaticamente com o computador por padrão e permanecerá em execução na bandeja do sistema. Não feche ou saia do programa. Em situações desconhecidas e incontroláveis, desconecte e reconecte a interface TYPE-C para reiniciar o hardware.', 293.92, 254.64, NULL, 'Computers & Accessories > Monitors', 'https://cf.shopee.com.br/file/sg-11134201-823r0-mp7ypt403dov07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F42930826947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
