INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999435204', 'Kit 02 Amaciantes Concentrados Brésil 1L Ypê por L''occitane', 'Kit 02 Amaciantes Concentrados Brésil 1L Ypê por L''occitane Transporte-se para uma experiência perfumada e surpreendente! Um amaciante para roupas com perfume inspirado em Brésil, fragrância marcante e sofisticada de L''Occitane au Brésil, que combina notas cítricas e verdes com um corpo floral transparente e fundo amadeirado. Ao escolher essa versão da Ypê, você leva para casa não apenas um amaciante eficiente no cuidado com os tecidos, mas também uma experiência sensorial inspirada na perfumaria fine fragrance. Indicação de Uso: - Ideal para roupas brancas ou coloridas de uso diário, como camisetas, lençóis, toalhas, entre outros itens de vestuário e cama, trazendo cuidado especial a todas as peças. Modo de Uso: - Use meia tampa (20ml) do produto para 11kg de roupas; - Deixe agir por 10 minutos e complete o processo. Fragrância: Inspirado em Brésil Embalagem: 02 frascos de 1L cada', 64.19, 64.19, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/br-11134207-820lj-mnop1ncjkmwyf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F23999435204', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
