INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297618409', 'Acabamento Para Registro Base Docol Up 1/2 3/4 1 Cromado Celite', 'SOBRE O PRODUTO Este é um produto da marca Celite, conhecida no mercado por fabricar acessórios para banheiro e cozinha. Faz parte da linha Up e é ofertado na cor prata com acabamento cromado e brilhante. A torneira é a parte externa do registro geral, conhecido também como gaveta ou pressão. É só girar para um dos lados e liberar a água, invertendo o movimento para interromper o abastecimento de rede externa ou reservatório. As bitolas de acabamento medem 1", 1/2" e ". Ela é compacta, com base arredondada e torneira com quatro hastes, fácil de segurar. DIFERENCIAIS: - MAIS DURABILIDADE: confeccionado em liga de cobre e plásticos de engenharia, possui longa vida útil, com 10 anos de garantia. - DESIGN CLEAN E ATEMPORAL: possibilita facilidade na harmonização em diferentes ambientes de seu imóvel. - FÁCIL INSTALAÇÃO: fácil de instalar e de acessar para a manutenção, promove praticidade no controle da vazão de água em seu cômodo. INFORMAÇÕES TÉCNICAS: - Aplicação: Parede - Material: Latão - Acabamento: Cromado - Formato: Quadrado - Volante: Cruzeta - Material: LATÃO + Canopla Em Abs - Acompanha válvula: Não - Acompanha flexível: Não - Bitola do Acabamento de Registro: 1", 1/2" e 3/4" - Registro Indicado: Gaveta e Pressão - Base Indicada para o Acabamento de Registro: Padrão Docol - Diâmetro do Acabamento de Registro: 15 mm, 20 mm e 25 mm DIMENSÕES - Altura: 6,4cm - Comprimento: 7,5cm - Largura: 5,5cm - Peso: 170g CONTEÚDO DA EMBALAGEM - 1 Acabamento de registro base reforma 1/2'''', 3/4'''' e 1'''' GARANTIA A Celite oferece 10 anos de Garantia em seus metais contra defeitos de fabricação. SOBRE A FABRICANTE A Celite foi fundada em 1941, com o nome de Porcelite, uma das primeiras indústria de louças sanitárias do Brasil. Seus fundadores foram dois engenheiros decididos a fabricar no Brasil as louças sanitárias vitrificadas, que, antes desta data, eram importadas. Atualmente a Celite tem soluções completas para seu banheiro, com linhas de louças, metais, acessórios, banheiras e móveis. Mais qualidade e segurança em seu banheiro.', 67.9, 67.9, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd75-lx16z2kanxca09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F22297618409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
