INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298051849', 'Pulseira Feminina de Prata 925 Patuá com Coração, Patinha e Osso', 'Pulseira Feminina de Prata 925 Patuá com Coração, Patinha e Osso A Pulseira Feminina de Prata 925 Patuá com Coração, Patinha e Osso é um acessório encantador que celebra o amor pelos pets e traz um toque de estilo único. Com elementos que representam carinho, lealdade e alegria, essa peça é perfeita para quem ama expressar sua paixão pelos animais de forma delicada e sofisticada. Especificações Tamanho: 18cm Largura: 3mm Tamanho do Coração: 11mm Tamanho da Patinha: 12mm Tamanho do Osso: 11mm Peso: 2,6g Material: Prata 925 Características Principais Confeccionada em Prata 925, garantindo alta qualidade e durabilidade Charme de patuá com design delicado: coração, patinha e osso Simbolismo especial para amantes de pets Acabamento impecável, ideal para uso diário ou presente Descrição Detalhada Com um design delicado e repleto de significado, a Pulseira Feminina de Prata 925 Patuá com Coração, Patinha e Osso é mais do que um acessório, é uma declaração de amor pelos seus amigos de quatro patas. Cada detalhe foi cuidadosamente pensado para trazer uma combinação perfeita entre elegância e simbolismo. A patinha representa a lealdade, o osso remete ao cuidado e o coração simboliza o amor incondicional. Feita em Prata 925, é uma peça resistente e duradoura, ideal para quem busca acessórios que expressem sua personalidade. Cuidados com o Produto Para manter sua pulseira sempre linda, evite expor a peça a produtos químicos e armazene-a em local seco. Use uma flanela macia para limpeza e conserve o brilho e a beleza da prata. Compre Agora Mostre seu amor pelos pets com a Pulseira Feminina de Prata 925 Patuá com Coração, Patinha e Osso. Adicione-a ao seu carrinho e leve um toque de carinho e estilo para o seu dia a dia!', 155.0, 115.0, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m35eybruht5h53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F23298051849', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58164646863', 'Corretivo Líquido de Alta Cobertura, Longa Duração à Prova d''Água, Controle de Oleosidade, Disfarça Manchas e Olheiras,', '💡 Cobertura completa sem esforço: Disfarça naturalmente olheiras, manchas de acne, imperfeições, vermelhidão e manchas escuras, sem pesar. ⏳ Longa duração & à prova d’água: Dura o dia todo; resistente ao suor e não transfere — não craquela nem escorre. 🌟 Leve & respirável: Textura sedosa e não abafante desliza sobre a pele para um acabamento natural e impecável. ✨ Ilumina & uniformiza o tom: Ilumina instantaneamente o aspecto opaco e uniformiza a pele para uma base matte e perfeita. 🖌️ Correção pontual fácil: Aplicador preciso para uma mistura fácil e precisa — ideal para iniciantes.', 42.0, 29.19, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134253-82580-mqy0033rryth93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F58164646863', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
