INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694384619', 'Chaleira Elétrica Inox Térmica Bule Com Tampa Café Chá Inox 110v/220v Onistek ON-CL200', 'Chaleira Elétrica Onistek ON-CL200 combina eficiência, design moderno e praticidade para o dia a dia. Com capacidade de 1,8 litros e desligamento automático, é ideal para aquecer água de forma rápida e segura. Seu revestimento em aço proporciona durabilidade, enquanto o cabo de alimentação de 75cm garante mobilidade no uso. Disponível em duas versões, atende tanto instalações com voltagem de 127V quanto de 220V, adaptando-se às necessidades do ambiente. Compacta e funcional, é perfeita para uso em cozinhas, escritórios ou espaços com rotina intensa. ESPECIFICAÇÕES: - Modelos: ON-CL200-110V / ON-CL200-220V - Capacidade: 1,8 Litros - Altura: 25 cm - Diâmetro da base: 16 cm - Largura com alça: 21 cm - Revestimento: Aço - Frequência: 60 Hz - Cabo de alimentação: 3 x 0,75 x 75 cm - Função: Desligamento automático POTÊNCIA E VOLTAGEM: - Modelo ON-CL200-110V: 1200W / 127V - Modelo ON-CL200-220V: 1500W / 220V CONTEÚDO: 01 Chaleira Elétrica Onistek ON-CL200 (conforme modelo selecionado)', 82.5, 57.51, NULL, 'Home Appliances > Kitchen Appliances > Kettles', 'https://cf.shopee.com.br/file/sg-11134201-824h6-mefs96eproxv83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F23694384619', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897725408', 'Condicionador Tio Nacho Anti-idade 415ml', 'O peso líquido do conteúdo é de 415ml. Tio Nacho Anti-Idade é perfeito para fortalecer os cabelos, proporciona uma aparência mais jovem, Rejovelhecendo os fios. Tio Nacho Anti-Idade é indicado para cabelos mais fracos e opacos. Feito com 10x mais Geleia Real. Nossa tecnologia foi criada para devolver a nutrição e brilho do cabelo, fortalece e proporciona uma aparência mais jovem. O Tio Nacho Anti-Idade é perfeito para nutrição profunda, fortalecimento e brilho, deixando seus cabelos lindos e joviais. Aplique o condicionador Tio Nacho Anti - Idade após o shampoo, deixe atuar por alguns minutos e, em seguida, enxágue.', 49.08, 41.9, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m310bstw2kete6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1284050214%2F20897725408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
