INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40230617599', 'Anel de Prata 925 Regulável Liso', 'Anel de Prata 925 Regulável Liso Versatilidade e elegância em uma joia essencial. O Anel de Prata 925 Regulável Liso é perfeito para quem busca um acessório clássico, confortável e fácil de ajustar. Com design minimalista e acabamento polido, essa peça combina com qualquer estilo e é ideal para o uso diário. Detalhes do Anel Largura: 3mm Peso médio: 1,8g Material: Prata 925 legítima Modelo: Regulável (ajuste prático ao dedo) Destaques da Joia Design liso, clássico e atemporal; Aro regulável que proporciona ajuste confortável e versátil; Produzido em Prata de Lei 925, com alta durabilidade; Acabamento polido com brilho elegante; Ideal para usar sozinho ou em mix de anéis; Excelente opção para presentear sem preocupação com tamanho. Cuidados com sua Joia Evite contato com produtos químicos, perfumes e cremes; Guarde em local seco e protegido da umidade; Limpe com flanela específica para prata para manter o brilho da peça. O Anel de Prata 925 Regulável Liso é a escolha ideal para quem busca praticidade, elegância e versatilidade em uma única joia. Uma peça especial da Aqua Joias, feita com qualidade e acabamento impecável.', 98.8, 75.0, NULL, 'Fashion Accessories > Rings', 'https://cf.shopee.com.br/file/br-11134207-820lw-mnvlxzu67ugy10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F40230617599', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
