INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55557474043', 'Boneco Funko Pop! NBA Warriors - Jimmy Butler III', 'Destaque sua coleção de basquete com o Boneco Funko Pop! Jimmy Butler III, trazendo o astro da NBA em seu uniforme azul Icon Edition do Golden State Warriors. Com aproximadamente 9 centímetros de altura e um visual cheio de presença, este colecionável captura toda a intensidade e o estilo de Butler dentro e fora das quadras. Ideal para fãs dos Warriors, admiradores do jogador e colecionadores que buscam uma peça marcante, este Funko Pop! adiciona personalidade, autenticidade e energia ao seu display esportivo.', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-8262c-mm29srggs3d045', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F55557474043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
