INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594017955', 'Ar Condicionado Split Hi Wall Springer Midea AirVolution 18000 BTU/h Frio 42AFFCI18S5 - 220 Volts', 'Ar Condicionado Split Springer Midea AirVolution 18.000 BTUs Frio 42AFFCI18S5 – 220 Volts Conforto e eficiência para o seu ambiente: O Ar Condicionado Split Springer Midea AirVolution 18.000 BTUs foi desenvolvido para oferecer climatização rápida e eficiente, proporcionando conforto térmico em residências ou ambientes comerciais com segurança e economia.Robustez e durabilidade:Serpentina de cobre: material resistente e de alta condutibilidade térmica, garantindo eficiência na troca de calor.Proteção GOLD FIN®: cobertura extra contra corrosão na unidade externa, aumentando a durabilidade do equipamento. Funções que facilitam o seu dia a dia:Função Turbo: opera em capacidade máxima, atingindo a temperatura programada em menos tempo, ideal para dias de calor intenso.Função Dormir: ajusta automaticamente a temperatura durante o sono, oferecendo conforto e economia de energia. Diferenciais do Ar Condicionado Springer Midea AirVolution 18.000 BTU/s: Potência de 18.000 BTU/h: climatização eficiente para ambientes médios a grandesSerpentina de cobre com alta condutibilidade térmicaUnidade externa com proteção GOLD FIN® contra corrosãoFunção Turbo: resfriamento rápidoFunção Dormir: conforto e economia durante o sono O Ar Condicionado Split Midea AirVolution 18.000 BTUs Frio é a escolha ideal para quem busca desempenho, durabilidade e praticidade em um único equipamento. Imagens meramente ilustrativas.', 3388.0, 3388.0, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-82581-mqz3k4ii445da1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F23594017955', NULL, NULL, '2026-07