INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898655284', 'Voltímetro e Marcador de Temperatura Digital LED à Prova de Vibração Knup KP-S142', 'Medidor Automotivo 2 em 1 9-36V Knup oferece uma combinação eficiente de monitoramento de tensão e temperatura da água, ideal para motoristas que buscam segurança, precisão e durabilidade. Com design compacto e moderno, é fabricado em ABS e acrílico de alta resistência. Sua tela digital em LED com retroiluminação permite leitura clara em qualquer condição de iluminação. Opera em ampla faixa de tensão e suporta variações extremas de temperatura, garantindo performance estável e confiável. Conta com tecnologia antirreflexo e antivibração, além de oferecer alta precisão nos dados fornecidos, sendo perfeito para veículos de pequeno, médio e grande porte. ESPECIFICAÇÕES: - Modelo: KP-S142 - Material: ABS + Acrílico - Tensão de operação: 9-36V - Temperatura de trabalho: -40°C a 50°C - Umidade relativa: 45% - 75% UR - Faixa de medição de tensão: 9V a 39V - Faixa de medição de temperatura: \~10°C a \~120°C - Dimensão do sensor: 10mm - Tela: LED com retroiluminação - Características: Antirreflexo, Antivibração, Alta precisão, Alta estabilidade CONTEÚDO: 1 Medidor Automotivo', 82.99, 81.33, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rasq-mb5mgiw8of375a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F22898655284', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12046339410', 'Ração Biofresh Para Cães Adultos de Raças Pequenas e Mini Seleção de Carnes, Frutas e Legumes 3kg', 'Ração Biofresh Cães Adultos Raças Pequenas e Minis A Ração Biofresh Cães Adultos Raças Pequenas e Minis é inovador e diferente porque possui alta inclusão de ingredientes frescos, diretamente da natureza. O resultado é um alimento completo e equilibrado que se destaca por elevar a nutrição dos cães de raças pequenas e mini ao seu mais alto patamar. A Tecnologia Biofresh garante a preservação deste alimento de forma segura e 100% natural, sem adição de conservantes artificiais. - Possui ingredientes naturais e de alta qualidade; - Tem palatabilidade reforçada para agradar ao animal, - Proporciona uma alimentação completa e balanceada.', 185.9, 176.61, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf2uf5wkb284ea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F12046339410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
