INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199182719', 'Som Bluetooth Bob Usb Pen Drive Fm Alto Falante 6x9 Bravox', 'Destaques do Produto: • Som Potente e Nítido: Equipada com 1 Alto Falante 6x9 da renomada marca BRAVOX, esta Caixa Bob oferece graves encorpados e agudos claros, garantindo uma experiência sonora superior para sua casa. • Conectividade Completa: O Rádio MP3 1 DIN possui Bluetooth, permitindo que você toque suas músicas favoritas diretamente do celular, além de entradas USB (Pendrive) e Rádio FM. • Pronta para Usar (Plug and Play): O kit já vai totalmente montado dentro da caixa de carpete, incluindo a fonte 12V, o rádio e o alto falante, com toda a fiação pronta. É só ligar na tomada e aproveitar! • Design Compacto e Elegante: Com acabamento em carpete, a caixa tem dimensões ideais para ser colocada em qualquer cômodo, sem ocupar muito espaço. Conteúdo da Embalagem (Tudo Já Montado!): • 1 Alto Falante BRAVOX 6x9 • 1 Caixa em Carpete (Bob) • 1 Fonte de Alimentação 12V (Residencial) • 1 Rádio com Bluetooth, USB e FM Itens acima já irão montados na caixa com todos os fios conectados e prontos para uso.', 299.0, 299.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgo0fdxkghdw64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1403252598%2F22199182719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50656382144', 'Frente Para Pistola 700W DEFFER - DFPP700', 'Peça de reposição original para a parte frontal da Pistola de Pintura 700W modelo DFPP700 da marca Deffer. Ideal para substituição em caso de desgaste ou danos, garantindo o correto funcionamento e desempenho do equipamento. Fabricada com material resistente, proporciona encaixe preciso, vedação adequada e mantém a eficiência na pulverização da tinta. Produto indicado exclusivamente para o modelo DFPP700 700W. Em caso de dúvida sobre compatibilidade, consulte antes da compra.', 69.9, 59.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81zuf-ml3iutcksphc2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F709990445%2F50656382144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
