INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55402550769', 'Riscadeira/Cortador de Piso Porcelanato 120cm Vollekz Com Laser Profissional 23 Rolamentos', 'A Riscadeira Profissional VOLLEKZ VKZ1200 foi projetada para instaladores que exigem precisão, estabilidade e acabamento limpo no corte de porcelanato e pisos cerâmicos. Com 23 rolamentos de alta precisão – mais que a maioria dos modelos do mercado – o carro desliza com suavidade extrema, garantindo riscos uniformes e cortes com borda limpa mesmo em peças espessas. Equipada com guia a laser vermelho, régua milimetrada e esquadro lateral, a VKZ1200 entrega alinhamento perfeito e repetibilidade nos cortes. Sua estrutura reforçada em aço zincado oferece rigidez, durabilidade e confiabilidade profissional para uso contínuo em obras. Vantagens: - 23 rolamentos de precisão para deslizamento extremamente suave - Guia a laser vermelho para alinhamento imediato do corte - Estrutura metálica reforçada, garantindo estabilidade e longa vida útil - Esquadro lateral com régua milimetrada e trava para cortes repetitivos - Capacidade real de corte de 120 cm (1,20 m) - Suporta peças de até 12 mm de espessura - Base antiderrapante texturizada para evitar movimentação da peça - Apoio lateral rebatível para porcelanatos grandes - Rompimento firme e limpo, reduzindo lascas e retrabalho - Roldanas de transporte para facilitar deslocamento - Ideal para instaladores que precisam de precisão e produtividade Especificações técnicas: - Aplicações: cortes retos, diagonais, triangulares e em tiras - Comprimento máximo de corte: 120 cm - Comprimento total: 128 cm - Espessura suportada: 6 a 12 mm - Guia a laser: Sim (alimentação por 2 pilhas AAA – 2 inclusas) - Rolamentos: 23 unidades - Estrutura: Aço zincado reforçado - Base: Borracha antiderrapante - Guias laterais: Esquadro milimetrado com trava - Uso indicado: Profissional, contínuo e pesado Aplicações: - Instalação de porcelanatos e pisos cerâmicos - Obras residenciais, comerciais e industriais - Cortes retos e diagonais de alta precisão - Peças grandes e espessas (60×60, 80×80, 120×60, etc.) Conteúdo da embalagem: - 01 Cortador Profissional VOLLEKZ VKZ1200 - 01 Esquadro lateral milimetrado - 01 Barra de apoio rebatível - 01 Carro de corte com riscador - 01 Kit de chaves de montagem - 02 Pilhas AAA (Palito) Obs.: Não acompanha luvas nem óculos de proteção Marca e modelo: Marca: VOLLEKZ Modelo: VKZ1200 Garantia do Fabricante: 90 dias', 976.35, 799.88, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjfkhkp3x62pae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406223656%2F55402550769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40708602031', 'Mulheres Que Caminham Juntas', '📝 Descrição: Mulheres Que Caminham Juntas é uma obra escrita por oito autoras cristãs que compartilham reflexões sobre comunhão, discipulado, serviço e aconselhamento. O livro convida mulheres a viverem a fé em comunidade, superando os desafios da vida com amor sacrificial, boas conversas e apoio mútuo. Ideal para grupos femininos, estudos bíblicos e leitura pessoal, esta obra inspira mulheres a edificarem umas às outras com seus dons e talentos, apontando sempre para Cristo. 📄 Ficha técnica: Título: Mulheres Que Caminham Juntas Autoras: Claúdia Lotti, Ana Paula Araújo, Lai e outras Editora: Fiel Ano de publicação: 2023 ISBN: 9786557233894 Idioma: Português Número de páginas: 160 Formato: Brochura Dimensões: 21 cm x 14 cm Peso: 250 g Categoria: Vida cristã, discipulado feminino, comunhão Indicação etária: A partir de 14 anos 🔍 Palavras-chave: mulheres que caminham juntas, claudia lotti, discipulado feminino, comunhão cristã, vida em comunidade, editora fiel, livro para mulheres, fé compartilhada, aconselhamento bíblico', 40.81, 40.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc7x2dpj6odc57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F40708602031', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997641239', 'Rodízio Fixo De Borracha 125mm - 5 Polegadas - JST', 'Indicado para movimentação de móveis, bancadas, carrinhos, máquinas e equipamentos. Possui núcleo em chapa de aço zincado, proporcionando maior resistência contra oxidação/corrosão. Roda produzida em borracha maciça que não fura e proporciona uma rodagem macia e silenciosa. Dados técnicos: • Altura do rodízio: 150mm. • Diâmetro: 5pol – 125mm. • Largura da roda: 34mm. • Medidas da placa: 102mm x 84mm. • Espessura do garfo: 2,0 mm. • Capacidade de carga: 100kg. • Peso: 0,900kg. • Material da roda: Borracha. • Material da base: Chapa de aço zincada. • Tipo do eixo: com rolete. Produto Vendido por: Unidade', 31.67, 29.46, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262f-mksfxddq60w7cd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F20997641239', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
