INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209442121', 'Álcool Zumbi Tradicional', 'O Álcool Zumbi 46° INPM é ideal para a limpeza geral da casa, removendo sujeiras difíceis com praticidade e eficiência. Modo de uso: Aplique o produto sobre a superfície a ser limpa e espalhe com um pano. Para limpeza, utilize 100ml do produto para cada 1l de água. Produto não recomendado para superfícies sensíveis ao álcool.', 12.99, 12.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8258l-mqnem2vnml8u2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58209442121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794320447', 'Kit Cinto De Segurança Corsa Wind 3 Pontos Traseiro Estático', 'Somos a Vai de Peças, veio para se tornar, líder nacional em vendas, atendimento e estoque em cinto de segurança. Preparamos um kit cintos de segurança para bancos traseiros em formato estático (não retrátil) e somente na cor preta, com as melhores marcas, e o melhor preço do mercado. E com mais um kit Parafusos de brinde, para você dar uma renovada no seu carro. O kit é composto por: 02 unidades: Cinto de segurança estático 3 pontos regulável. 01 unidade: Cinto de segurança abdominal regulável. 01 kit: parafusos de fixação. Características: Materiais dos componentes: Poliéster, Aço carbono temperado e ABS. 1 anos de garantia. Materiais dos componentes: Poliéster, Aço carbono temperado e ABS. 1 ano de garantia. Medidas: Macho 3 pontos: 2,15 metros Macho abdominal: 1,20 metros Fêmea: 50 cm O uso do cinto de segurança nos bancos dianteiros já é prática costumeira dos brasileiros. No entanto, a falsa sensação de segurança nos bancos traseiros faz com que muitos passageiros ainda não utilizem os cintos de segurança traseiros. Em um acidente, quando as pessoas do. Benefícios do uso do cinto de segurança: Reduz o risco de ferimentos graves em acidentes de trânsito. Mantém o corpo estabilizado, evitando o impacto contra o volante ou painel. Garante segurança e conforto durante a condução. Atende às normas de segurança veicular exigidas por lei. Evita multas e pontuação na CNH por uso incorreto. Indicado para todos os veículos: carros, caminhonetes e utilitários. Fácil instalação e reposição, ideal para manutenção preventiva. Custo-benefício alto, sendo essencial para a segurança automotiva. Recomendações: - Instalar com apoio de profissional qualificado. - Garantia de 6 meses.', 130.0, 130.0, NULL, 'Fashion Accessories > Additional Accessories > Cufflinks', 'https://cf.shopee.com.br/file/sg-11134201-7rdx0-mdjik3sj9se4b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1604698269%2F22794320447', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
