INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693842761', 'Regulador De Pressão Para Chopp Cerveja Co2 Engate Rápido', 'O Regulador de Pressão W34 CHOPP DA WWSOLDAS é a solução ideal para quem busca eficiência na extração e carbonatação de chopp e cerveja. Com uma pressão máxima de 60 psi, este manômetro regulador garante um controle preciso, permitindo que você aproveite cada gota da sua bebida favorita com a qualidade que merece. Fabricado em alumínio e latão, o W34 CHOPP é robusto e durável, projetado para suportar as exigências do ambiente de trabalho. Sua conexão inferior facilita a instalação e o manuseio, tornando-o uma escolha prática para bares, restaurantes e eventos. Recomendado para a extração e carbonatação de cervejas, este regulador é um aliado indispensável para os amantes de chopp. A marca WWSoldas é reconhecida pela sua qualidade e confiabilidade, assegurando que você tenha um produto que atenda às suas necessidades. Válvula Reguladora De Pressão Co2 Saída Dupla c/ engate rápido Com 2 escalas de medição Válvula de alívio libera com 4,5bar Medidor da Pressão Interna Barril: 0 - 60 PSI (0 - 6 bar) Medidor da Pressão Interna do Cilindro de CO2: 0 - 3500 PSI (0 - 250 bar) Entrada padrão CGA320 Acompanha anel reserva Acompanha 1 engate rápido DUOTIGHT p/ rosca 1/4" p/ mangueira semi rígida diâmetro externo 3/8" Acompanha chave cortesia', 329.0, 279.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7jej6f81rnu94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F283838689%2F22693842761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48852190681', 'Espelho Orgânico Com Led Grande Decorativo de Parede Moderno 90x40cm Quarto Sala Hall Closet Lavabo', 'Espelho Orgânico Magnus com LED 90x40 cm – Luz Quente e Fria, Vidro Lapidado Modernize seu ambiente com o Espelho Orgânico Magnus 90x40cm com LED. Com design funcional e acabamento sofisticado, é ideal para banheiros, salões de beleza, consultórios, quartos e escritórios. Além de proporcionar iluminação precisa, o espelho contribui para um visual clean e elegante, adaptando-se facilmente a diversos estilos de decoração. Benefícios do Produto: Design moderno e funcional: espelho orgânico com bordas lapidadas que valorizam o ambiente Iluminação LED de alta performance: escolha entre luz quente (3000K) ou fria (6500K), conforme a necessidade Vidro resistente: material temperado de 3 mm com proteção contra impactos e riscos Instalação facilitada: suporte fixo e manual ilustrado para montagem rápida e segura Versátil e seguro: ideal para ambientes residenciais ou comerciais Especificações Técnicas; Dimensões: 150 cm de altura x 40 cm de largura Material: Vidro lapidado, 3 mm de espessura Iluminação: LED com interruptor duplo (quente 3000K / fria 6500K) Alimentação: Bivolt (127V/220V) Garantia: 90 dias contra defeitos de fabricação Como Instalar: Fixe o suporte na parede utilizando os parafusos e buchas fornecidos, e pendure o espelho com cuidado. A superfície deve estar limpa, seca e nivelada para garantir a segurança da instalação. Embalagem Reforçada e Envio Seguro: O espelho é enviado com embalagem reforçada e materiais de proteção, garantindo que chegue em perfeito estado até você. Garantia do vendedor: 90 dias', 299.9, 229.9, NULL, 'Home & Living > Decoration > Mirrors', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgcltom21a8748', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248180593%2F48852190681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
