INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993043426', 'Pneu Moto Borilli Aro 21 7 Days Enduro 90/90-21 57R TT - Dianteiro', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. O Borilli 7 Days Enduro é um pneu traseiro focado em desempenho e feito para quem ama o mundo Off-Road. Ele oferece performance excelente em terrenos intermediários e macios, uma vez que a banda de rodagem conta com blocos alternados que garantem mais estabilidade na hora da tração. A banda de rodagem do Borilli 7 Days Enduro tem blocos espaçados, que facilitam o sistema de autolimpeza e a durabilidade do pneu, diminuindo o atrito com pedras e detritos. O Borilli 7 Days Enduro é ideal para quem faz trilhas e encara qualquer terreno. Sobre a Borilli Há mais de 30 anos no segmento de alta performance Off-Road, a Borilli é uma fabricante de pneus nascida no Brasil. Com centro de desenvolvimento e pistas de teste, além do incentivo ao esporte, a Borilli tem como lema garantir o desempenho e a segurança de quem vive o mundo sobre duas rodas.', 412.73, 379.72, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd6x-lvj9a2p5sep375', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23993043426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993727920', 'Pneu Bridgestone Aro 16 Turanza ER300 205/55R16 91V', 'Marca: BRIDGESTONE Modelo: TURANZA ER300 Medida: 205/55R16 Largura: 205 Perfil: 55 Tamanho de Aro: 16 Índice de peso: 91 - 615 kg, 91 Índice de velocidade: V - 240 km/h, V Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Assimétrico UTGQ: 320AA Adesão à àgua: E Eficiência energética: C Ruído externo: 69 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. O Bridgestone TURANZA ER300 representa a evolução da tecnologia Bridgestone. Pensado para equipar veículos de alta performance, conta com revolucionário desenho assimétrico na banda de rodagem que proporciona grande conforto e estabilidade aos carros de luxo. Da linha Bridgestone Turanza Pneus prêmio, o modelo possui grandes blocos nos ombros, garantindo, além de ótimo desempenho tanto em pista seca quanto molhada, maior controle do carro durante altas velocidades e curvas. Sobre a marca Bridgestone Nascida em 1931 no Japão, a Bridgestone tem se dedicado a criar pneus que oferecem uma experiência única ao volante. Marcada por inovação, desempenho e compromisso com a segurança, os pneus Bridgestone proporcionam confiança em cada curva. Líder global no mercado de pneumáticos, a Bridgestone também estabeleceu sua marca com pneus de alta durabilidade e resistentes ao desgaste. Com forte investimento em pesquisa e desenvolvimento, a marca japonesa utiliza tecnologia avançada para garantir que cada pneu seja sinônimo de excelência.', 629.32, 578.98, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd5a-m6oiehu25kbtb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23993727920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497509641', 'Jogo 2 Pneus Pirelli Aro 17 Scorpion HT 265/65R17 112T', 'Marca: PIRELLI Modelo: SCORPION HT Medida: 265/65R17 Largura: 265 Perfil: 65 Tamanho de Aro: 17 Índice de peso: 112 - 1120 kg, 112 Índice de velocidade: T - 190 km/h, T Tipo de Veiculo: SUV Tipo de terreno: AT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: SIMÉTRICO UTGQ: 520AB Adesão à àgua: C Eficiência energética: C Ruído externo: 73 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Você busca por um pneu eficiente tanto na terra quanto no asfalto? Então o Pirelli Scorpion HT é a resposta para a sua dúvida. Desenvolvido para rodar a maior parte do tempo no asfalto (70%), o modelo vai bem em trilhas leves (30%), sendo perfeito para você que usa Picapes e ama versatilidade. Com desenho moderno e otimizado da banda de rodagem, o Pirelli Scorpion HT conta com novos compostos para diminuir a resistência ao rolamento. Essa composição ajuda na economia de combustível. Além disso, é ótimo para o dia a dia e viagens, pois seu design evita que o ruído do atrito com o asfalto entre na cabine. Sobre a marca Pirelli A Pirelli nasceu na Itália há mais de 100 anos, em Milão. Com longa tradição na construção de pneus, a marca produz soluções para carros, motos, tratores, caminhões e ônibus e possui fábricas espalhadas pelo mundo. A Pirelli é a atual fornecedora de pneus da Fórmula 1, a principal categoria do automobilismo mundial, e possui longa tradição em pneus de alto desempenho.', 2315.76, 2130.5, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdy2-lxlo3simmoh2f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22497509641', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
