INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699568075', 'Cápsula Dolce Gusto Café com leite e Chocolate Branco Café Italle 20 Und', 'Neste kit Café Dolce Gusto você ira receber: 01 - Caixa Café com leite 10 Cápsulas 01 - Caixa Chocolate Branco 10 Cápsulas CAFÉ COM LEITE ITALLE: Criadas para os verdadeiros apreciadores de café, descubra o prazer de um café perfeito com o Café com Leite Italle. Nossas cápsulas oferecem uma combinação harmoniosa de café premium e leite cremoso, proporcionando uma experiência sensorial inigualável a cada xícara. Deixe sua bebida ainda mais gostososa adicionando chantilly e um toque de achocolatado em pó. CHOCOLATE BRANCO O clássico chocolate Branco quente, cremoso e delicioso, para envolver seu paladar. Nossa versão traz o melhor do cacau brasileiro, com leite de alta qualidade, para que você saboreie uma bebida equilibrada e surpreendente. Finalize com um pouco de chantili para potencializar ainda mais a textura. Contém leite e derivados. Pode conter derivado de soja. Contém lactose. Experimento seu momento Italle!', 71.8, 39.49, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-7rfi5-m3kp217ydgejf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F334540655%2F21699568075', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
