INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899547585', 'Lápis de Cor 15 Cores Neutras Supersoft Faber Castell - 1 Estojo', '*Produto certificado de acordo com as portarias INMETRO Nº: Registro ?000777/2013 Especificações técnicas: Marca: Faber Castell; Referência: 120715SOFTCN; Caracteristicas do produto: Lápis De Cor Supersoft 15 Cores Neutras Faber Castell - 1 Estojo Com 15 Cores; Embalagem: 1 Estojo Com 15 Cores Descrição: O estojo com 15 cores de lápis de cor Supersoft Neutras da Faber Castell oferece uma seleção versátil para suas criações artísticas. Com cores neutras suaves e sutis, este conjunto é ideal para adicionar profundidade e sutileza aos seus desenhos, colorações e ilustrações. Os lápis de cor Supersoft Neutras da Faber Castell proporcionam uma aplicação suave e consistente, garantindo que suas criações tenham um acabamento delicado e refinado. Este estojo é perfeito para artistas de todas as idades que desejam explorar e experimentar com cores neutras que complementam uma variedade de estilos e temas. Com as cores neutras Supersoft Faber Castell, você terá as ferramentas necessárias para criar trabalhos de arte elegantes e sofisticados que destacam a beleza dos tons mais suaves.', 118.41, 118.41, NULL, 'Stationery > Art Supplies > Color Pencils', 'https://cf.shopee.com.br/file/sg-11134201-7rdxe-m1im74w99m4o87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306190243%2F19899547585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
