INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19961907329', 'Amortecedor Honda Fit 2003 A 2008 Dianteiro Motorista Nakata', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação FIT EX/ S 1.5/ EX 1.5 FLEX 16V 5P MEC. 2005 até 2008 FIT EX/S/EX 1.5 FLEX/FLEXONE 16V 5P AUT. 2005 até 2008 FIT LX 1.4/ 1.4 FLEX 8V/16V 5P AUT. 2004 até 2008 FIT LX 1.4/ 1.4 FLEX 8V/16V 5P MEC. 2004 até 2008 FIT LXL 1.4/ 1.4 FLEX 8V/16V 5P AUT. 2004 até 2008 FIT LXL 1.4/ 1.4 FLEX 8V/16V 5P MEC. 2004 até 2008 Conteúdo Da Embalagem > 1 Amortecedor Dianteiro > 1 Certificado de Garantia > > Observação Modelo Antigo Tipo de Veículo para Carros Marca A Nakata é fabricante de autopeças para o mercado de reposição para veículos leves, pesados e motocicletas, está presente no Brasil há mais de 65 anos. Possui uma linha completa de componentes para suspensão, transmissão, freios, motor e motopeças, e é líder no mercado de reposição na linha de pivôs de suspensão e juntas homocinéticas. > Com pioneirismo, qualidade e compromisso com o mercado, a Nakata é reconhecida pela alta performance de seus produtos e elevado padrão de serviços. O Produto O amortecedor é um componente fundamental do sistema de suspensão do seu Fit. A estabilidade, conforto e segurança ficam diretamente comprometidos se os amortecedores não estiverem atuando corretamente. Isso é pneus e demais componentes da suspensão. > Importante > > > > • Tempo de Garantia: 2 anos ou 50 mil km > • Solicite ao seu mecânico que seja feito o escorvamento do amortecedor antes de sua instalação > • Valor unitário > • Imagem meramente ilustrativa > • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. > Modelo Amortecedor Pressurizado EAN 7890903001777 Código do Fabricante HG31118 Posição Dianteiro Comprimento Aberto 534,5 mm Comprimento Fechado 356,5 mm Posição Dianteiro >', 274.83, 274.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7r995-lluavhw7h9h53d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F19961907329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
