INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22496700419', 'Coxim Motor Mercedes Benz 709 81 A 96 Dianteiro Traseiro', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação MERCEDES-BENZ 709 2P (DIESEL) 1981 até 1998 Conteúdo Da Embalagem 1 Coxim de motor Observação Motor OM 364 - OM 364A - OM 364LA Tipo de Veículo para Caminhões Marca A empresa paulistana, Indústria Rei, foi criada em 1960, na cidade de Cajuru. Mantém a preocupação voltada para a qualidade e tecnologia, reunindo equipamentos e processos de última geração na fabricação de peças automotivas de linha leve e pesada. A Indústria Rei tem produção de borracha natural através de seringal próprio, tendo capacidade de produzir produtos de alta qualidade. O Produto Os coxins são uma proteção contra a vibração do motor e do câmbio na carroceria. Em todos os veículos existem uma proteção, geralmente feita por uma peça de borracha, que fica entre o motor e a carroceria. Isso evita que a vibração do motor chegue ao veículo causando desconforto aos ocupantes. Coxim dianteiro e traseiro da suspensão do motor. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia: 3 meses. Valor unitário. Imagem meramente ilustrativa. Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. EAN 7898215794530 Código do Fabricante R375 REI Posição Dianteiro Traseiro Posição Dianteiro Traseiro', 131.34, 131.34, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbl4-lluiq8godkwzc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F22496700419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20457313134', 'Jogo Vela De Ignição Saveiro 1.6 2003 A 2006 Original Ngk', 'Aplicação VOLKSWAGEN SAVEIRO 1.6 MI/ 1.6 MI TOTAL FLEX 8V 2003 até 2004 SAVEIRO 1.6 MI/ 1.6MI CITY TOTAL FLEX 8V 2003 até 2006 SAVEIRO CROSSOVER 1.6 MI TOTAL FLEX 8V 2006 SAVEIRO SPORTLINE 1.6 MI TOTAL FLEX 8V 2006 SAVEIRO SUPER SURF 1.6 MI TOTAL FLEX 8V 2003 até 2006 Conteúdo Da Embalagem 4 Velas de Ignição Cor do Produto No Observação Ano: 05/2003 a 10/2006 Tipo de Veículo para Carros Marca A NGK fabrica itens automotivos desde 1959 no Brasil. Revestimentos porcelanizados, cabos de ignição e velas, terminais supressivos e cerâmicas técnicas fazem parte da extensa gama de produtos da empresa. Além disso, a NGK é uma companhia certificada pela ISO/TS 16.949 e obedece as diversas regras de referências internacionais de qualidade. Os mais de 1300 funcionários da NGK do Brasil passam por um absoluto programa de treinamento e integração à filosofia de trabalho, no qual são estimulados a contribuir com propostas de melhoria contínua em benefício da organização e da sociedade. O Produto A Vela de Ignição é quem fornece a centelha, também chamada de faísca elétrica, que é responsável por dar a partida no motor. Importante • Recomendamos que os produtos sejam aplicados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses • Valor referente ao jogo • Imagem meramente ilustrativa EAN 7897707510597 Código do Fabricante BKUR6ETC10 Combustível FLEX Combustível Flex', 104.08, 104.08, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rbmi-llt85l98rll1de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F20457313134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
