INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193832930', 'Capa Case Capinha Armorgear Gshield para Samsung Galaxy S24 Ultra Proteção Militar e Antiderrapante', 'Uma fortaleza de proteção para o seu Samsung Galaxy S24 Ultra! Com uma estrutura robusta, a Capa Armorgear da Gshield é construída para ser resistente. Os materiais duráveis absorvem choques, proporcionando uma barreira confiável contra danos acidentais do dia a dia. Além disso, a capa possui design lateral antiderrapante, garantindo uma aderência firme em suas mãos. Apesar da sua resistência, a Capa Armorgear é projetada com a ergonomia em mente. Ela é moldada para se encaixar perfeitamente ao seu Samsung Galaxy S24 Ultra, oferecendo proteção sem comprometer o acesso fácil aos botões e entradas do dispositivo. As bordas elevadas garantem que a tela e a câmera do seu celular estejam protegidas contra arranhões, quando colocado com a face para baixo. Proporcione uma defesa de nível militar ao seu Samsung Galaxy S24 Ultra com a Capa Armorgear da Gshield - onde proteção robusta encontra estilo arrojado! ESPECIFICAÇÕES - Material: Polipropileno de alta densidade - Marca: Gshield - Dimensões: Dimensões exatas do aparelho - Proteção: Contra impactos e riscos à tela - Certificações: Us Military - Cor: Preta COMPATIBILIDADE - Samsung Galaxy S24 Ultra', 142.97, 142.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rd6h-m785j3dksc1d82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22193832930', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
