INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16963294288', 'Película Hydrogel para Fitbit Sense - Gshield', 'Aumente a resistência com a película para Fitbit Sense A Película de Hydrogel para Fitbit Sense, da Gshield, garante proteção extra para a tela do seu dispositivo. Produzida com a tecnologia hidro nano pet + material semelhante ao silicone, são ultra resistentes contra riscos e com revestimento oleofóbico, atenuando as marcas de digitais na tela do aparelho; a película se adapta às extremidades curvadas, cobrindo todo o visor. ESPECIFICAÇÕES Material: Hidro nano pet + TPU Soft Gel Marca: Gshield - ( Gorila Shiel d ) Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High Definition Certificações: US Military Dimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais. COMPATIBILIDADE Fitbit Sense ITENS INCLUSOS 1x películas de hydrogel Kit de instalação GARANTIA 3 meses contra defeitos de fabricação', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/acc77700865243a817d96a7164d73f4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F16963294288', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
