INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693406929', 'Abraçadeira de Nylon Preto 3mm X 150mm 100un (80,0013) - Noll', 'A Abraçadeira de Nylon Preto 3mm X 150mm (80,0013) - Noll, é um dispositivo para fixação amplamente utilizado em funções domésticas e industriais. Fabricada em um nylon resistente junto a uma trava, sua principal função é agrupar e fixar os mais diversos tipos de materiais e diâmetros; proporcionando uma amarração segura e firme. As Abraçadeiras são muito conhecidas por sua versatilidade, durabilidade e resistência a condições adversas, como variações de temperaturas e umidade. Descrição do Produto: • Cada Embalagem contém 100 Unidades. • Fabricados em Nylon Resistente. • Bitola: 3mm X 150mm. • Cor: Preto. • Indicado para uso industrial e doméstico, para a aglomeração de diversos materiais e diâmetros. Referência: 80,0013. Cód. de Fábrica: 80,0013. Marca: Noll.', 11.89, 11.89, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdw6-m0vr3pqx60g930', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23693406929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693347041', 'Chave Combinada 25mm (41128/125) - Tramontina', 'A Chave Combinada 25mm (41128/125) - Tramontina, é uma ferramenta resistente e durável, produzida em aço especial com acabamento cromado, possui duas configurações de chaves: de um lado chave fixa e do outro chave estrela, sendo perfeita para apertar e afrouxar parafusos ou porcas de perfis quadrados e sextavados. Descrição do Produto: • Corpo forjado em aço especial e temperado. • Acabamento cromado. • Abertura das bocas calibradas. • Pescoço curto. • O teste de dureza é realizado em vários pontos para assegurar a resistência ao desgaste da chave durante o uso ininterrupto. • As aberturas das bocas das chaves de aperto são verificadas com gabaritos calibrados, o que garante seu perfeito acoplamento nos parafusos. • Alguns tipos de chaves de aperto são fornecidos em bitolas métricas e em polegadas, para o uso nos diversos fixadores disponíveis. • As ferramentas são produzidas e testadas conforme normas específicas. Referência: 41128/125. Marca: Tramontina.', 33.0, 33.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxo-m0kfciqd737o6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23693347041', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298236116', 'CERVEJA HOCUS POCUS AURA SLEEK 350ML PACK C/6UNID', 'VOCÊ ESTÁ COMPRANDO: CERVEJA HOCUS POCUS AURA SLEEK 350ML PACK C/6UNID ORIGEM: BRASIL SOBRE O PRODUTO Session IPA – 5% ABV – 350ml Aura é uma Tropical Hazy IPA de 5% ABV criada para os amantes das Hazys poderem desfrutar do estilo também no dia a dia, com sua leveza e alta capacidade de beber, sem perder aquela força aromática. O lúpulo Strata trouxe os aromas de maracujá para a primeira camada sensorial, como se a fruta estivesse sendo aberta nesse exato momento, e depois deixou um toque herbal e mineral no segundo plano. Por ser da família das Hazys, a Aura garante uma textura macia, aquela turbidez bem característica do estilo, e um finalzinho seco que pede pelo próximo gole. Tropical Hazy IPA, 5% ABV.', 165.59, 165.59, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-7rd6n-m6qv3da2hyfma5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F23298236116', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
