INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23615780751', 'Kit 2 Super Panos De Chão Grandes Em Microfibra Panão 80x50', 'Pano em Microfibra – Kit com 2 Unidades | Alta Absorção e Durabilidade Facilidade e eficiência para a limpeza do dia a dia! O Pano em Microfibra é fabricado com fibras longas e de alta qualidade, garantindo super absorção e resistência, sem soltar fiapos. Ideal para secar, limpar e cuidar de diferentes superfícies com praticidade e rapidez. Com medidas generosas de 50 cm x 80 cm, esses panos são versáteis e podem ser usados como toalhas para pet, na academia, hotelaria, banheiros e muito mais. ✅ Por que escolher o Pano em Microfibra? Super absorvente, facilita a secagem e limpeza Resistente e durável, não solta fiapos Tamanho ideal para diversas aplicações Prático e fácil de usar em diferentes ambientes Perfeito para pets, hotelaria, academias, viagens e limpeza doméstica 📏 Medidas: 50 cm x 80 cm (cada pano) 📦 Kit com 2 panos Observação: A cor do kit varia conforme estoque disponível. Garanta já o seu Pano em Microfibra e facilite suas tarefas com mais eficiência e praticidade!', 45.84, 23.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Cloths', 'https://cf.shopee.com.br/file/br-11134207-820ld-mn3aslv10av67d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F23615780751', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
