INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793273562', 'Cilindro Mestre Duplo Freio Pedal Pampa 85 A 97 Trw', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação FORD PAMPA 4X4 JEEP GL / L 1.6 1985 até 1995 PAMPA GHIA 1.6/1.8/DUO 1987 até 1995 PAMPA GL 1.6/ 1.8 1985 até 1997 PAMPA L 1.6 1985 até 1997 PAMPA L 1.8I / 1.8 1989 até 1997 PAMPA S 1.8 1985 até 1997 Conteúdo Da Embalagem 1 Cilindro Mestre Duplo de Freio Cor do Produto No Tipo de Veículo para Carros Marca Criada há mais de 100 anos, a TRW produz inovações sempre com qualidade e referência, estabelecendo-se no mercado mundial com uma reputação de excelência, graças a segurança e durabilidade de seus produtos. Combinando a sabedoria da experiência com um espírito pioneiro e a compreensão inata com a exploração de vanguarda, A TRW oferece uma extraordinária gama de produtos e serviços reconhecidos globalmente. O Produto O cilindro mestre, localizado dentro do capô do seu carro, é a peça responsável por acionar a pressão hidráulica dos freios de um automóvel. Quando o pedal de freio é acionado, os pistões da câmara interna do cilindro mestre pressionam o fluido de freios que se distribui por todo o sistema hidráulico e chega até as lonas e pastilhas de freio nas rodas. Importante • Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses • Valor Unitário • Imagem meramente ilustrativa • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7897483400273 Código do Fabricante RCCD0070.0 Sistema Ateteves Diâmetro 22,22mm', 165.63, 165.63, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7rdxn-m0wz05uckz0ae3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F22793273562', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
