INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259662947', 'Pão de Leite Paderrí', 'O Pão de Leite Paderrí é macio, levemente adocicado e perfeito para o café da manhã, lanche da tarde ou para um hot dog! Com a autêntica receita francesa, é uma excelente opção para toda a família. Cada embalagem contém 8 unidades, ideal para sanduíches, torradas ou para consumir puro.', 11.99, 11.99, NULL, 'Food & Beverages > Bakery > Breads', 'https://cf.shopee.com.br/file/sg-11134201-8260f-mj72kvggjcw6c9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555041%2F58259662947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
