INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54957067300', 'Tênis Infantil Menina Bee Happy Nina Nude e Rosa com Gritter Calce Fácil Velcro Duplo', 'Tênis Infantil Menina Bee Happy Nude e Rosa – Velcro Duplo com Glitter Dourado - O equilíbrio perfeito entre a delicadeza do nude e a energia do rosa para os looks mais fofos. Conforto Premium com Design Moderno para Meninas A Bee Happy apresenta um modelo que une a versatilidade das cores neutras com o toque lúdico que toda criança adora. Este tênis foi desenvolvido pensando na ergonomia infantil, garantindo que o pé respire enquanto recebe o suporte necessário para o desenvolvimento saudável. Destaques que você vai amar: - Praticidade no Calce: Os dois velcros frontais permitem um ajuste personalizado, ideal para pés mais gordinhos ou magrinhos, além de facilitar a rotina escolar. - Estética "Fashionista": O mix de texturas entre o material sintético liso, o glitter dourado e os detalhes em rosa chiclete transformam este calçado em uma peça de destaque no visual. - Solado Caixa Durável: O solado rosa não é apenas bonito; ele possui ranhuras antiderrapantes e alta resistência à abrasão, perfeito para brincadeiras em parques e pátios. - Interior Acolchoado: Forro em tecido macio que evita atritos e bolhas, proporcionando conforto do primeiro ao último uso do dia. Ficha Técnica: - Marca: Bee Happy - Cor: Nude (Bege Claro) / Rosa / Dourado - Fechamento: Velcro Duplo Reforçado - Detalhes: Coração em relevo e faixas de glitter - Solado: Borracha Flexível Rosa - Material: Sintético de Fácil Limpeza', 87.9, 66.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8261p-mlosyvbkw9hdb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404144117%2F54957067300', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18398028662', 'Relógio Technos Masculino Automático 1958 Prata - 8205OS/1P', 'Para celebrar o centenário da Technos, apresentamos uma coleção especial em homenagem ao ano de chegada da Technos ao Brasil, em 1958, com design inspirado nos relógios lançados pela marca na década de 50. São modelos com maquinismo automático japonês, com presença do day-date, 21 jewels e reserva de marcha de 42 horas. Todos os modelos da coleção apresentam lente com acabamento facetado, fundo de vidro rosqueado e acompanham estojo especial. Produto 100% em aço inoxidável, com maquinismo automático japonês e resistência à água de 50 metros.', 1190.0, 1090.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-825ay-mqvwpa31rjeob0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1332527814%2F18398028662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
