INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207049933', 'Pneu Moto Levorin 130/70-17 Matrix Sport 2 Traseiro Fazer 250 CBX 250 Original Sem Câmara', '🏍️ Pneu Moto Levorin Matrix Sport 2 130/70-17 Traseiro – Durabilidade e Custo-Benefício O Levorin Matrix Sport 2 é um pneu traseiro desenvolvido para motos street e de média cilindrada, oferecendo boa aderência, estabilidade e excelente custo-benefício. Com composto resistente e desenho eficiente da banda de rodagem, proporciona desgaste uniforme, boa quilometragem e segurança tanto no uso urbano quanto em pequenas viagens. Ideal para quem busca um pneu confiável, durável e acessível para o dia a dia. 📏 Especificações do Pneu ✔ Marca: Levorin ✔ Modelo: Matrix Sport 2 ✔ Medida: 130/70-17 ✔ Posição: Traseiro ✔ Tipo: Tubeless (sem câmara) ✔ Categoria: Street ⚙️ Diferenciais do Levorin Matrix Sport 2 ✅ Ótimo custo-benefício ✅ Boa aderência no seco e no molhado ✅ Alta durabilidade para uso urbano ✅ Desgaste uniforme ✅ Condução estável e confortável 🏍️ Compatibilidade (exemplos) Compatível com motos que utilizam 130/70-17 traseiro, como: • Yamaha Fazer 250 • Honda CBX 250 Twister • Kawasaki Ninja 250R • Suzuki GS500E (Sempre confirme a medida no manual da sua moto.) 📦 O que você recebe ✔ 01 Pneu Levorin Matrix Sport 2 130/70-17 Traseiro ✔ Produto novo e original 🛒 Compre com segurança ✔ Produto original com Nota Fiscal ✔ Envio rápido e seguro ✔ Produto novo e lacrado ✔ Garantia de fábrica', 555.44, 529.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-820mg-mlxfdoxd8cue2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1680878209%2F58207049933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
