INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250134381', 'Papel Acoplado Kraft 50x60cm 500 Unidades para Bolos, Tortas, Doces e Padaria', 'Papel Acoplado DuoFresh® Bakery Kraft 50x60cm – 500 Folhas para Bolos, Tortas, Doces e Assados O Papel Acoplado DuoFresh® Bakery Kraft 50x60cm foi desenvolvido especialmente para quem busca qualidade, proteção e uma apresentação profissional na embalagem de alimentos. Ideal para bolos caseiros, tortas, doces, pães, salgados e assados, ele valoriza seus produtos e proporciona uma excelente experiência aos clientes. Produzido pela Intercarta®, empresa pioneira e líder no segmento de papel acoplado no Brasil, o DuoFresh® utiliza tecnologia exclusiva que ajuda a conservar os alimentos frescos, protegidos e saborosos por mais tempo. Sua composição combina papel kraft de celulose virgem com uma película de polietileno de alta densidade, oferecendo maior resistência, higiene e segurança alimentar. Perfeito para uso em padarias, confeitarias, docerias, casas de bolos, rotisseries, cozinhas gourmet, cafeterias e serviços de delivery, garantindo uma apresentação diferenciada e profissional para seus produtos. Benefícios do Papel Acoplado DuoFresh® Bakery Kraft - Conserva o frescor e a qualidade dos alimentos por mais tempo - Ideal para embalar bolos, tortas, doces, pães e assados - Alta resistência e excelente barreira contra umidade e gordura - Embalagem com aparência sofisticada e profissional - Material seguro para contato com alimentos - Alternativa superior ao papel manteiga, papel seda e papel barreira - Produto 100% reciclável - Excelente custo-benefício para produção em grande escala Especificações Técnicas - Marca: DuoFresh® - Fabricante: Intercarta® - Modelo: Bakery Kraft - Material: Papel Kraft Pardo 30g/m² + Filme de Polietileno de Alta Densidade - Composição: Papel Kraft, PEAD, Cola PVA e Tinta Base Água - Medidas: 50 x 60 cm - Quantidade: 500 folhas - Cor: Kraft Pardo Aplicações Indicadas - Embalagem para bolos caseiros - Embalagem para tortas doces e salgadas - Embalagem para doces e sobremesas - Padarias e confeitarias - Casas de bolos - Rotisseries e cozinhas gourmet - Delivery de alimentos Sobre a Intercarta® A Intercarta® é referência nacional em papel acoplado há mais de 30 anos, produzindo milhões de unidades DuoFresh® anualmente. Reconhecida pela inovação, qualidade e alta capacidade produtiva, a empresa oferece soluções que garantem proteção, conservação e excelente apresentação para alimentos.', 351.24, 251.58, NULL, 'Stationery > Gift & Wrapping > Others', 'https://cf.shopee.com.br/file/sg-11134201-82581-mgf6b4uapz48cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F886490360%2F58250134381', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
