INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250296969', 'Saco Pequeno Para Pastel Barreira Gordura 500 Und Delivery - Branco', 'Saco Para Pastel CarryFoody Barreira Gordura O saco CarryFoody Barreira Gordura para pastel, da Intercarta, é a solução ideal para valorizar o seu alimento e melhorar a experiência do cliente. Feito com papel de alta qualidade, próprio para contato com alimentos, ele possui tratamento anti-gordura, evitando vazamentos e manchas na embalagem. Seu cliente consome o pastel com praticidade e higiene, mantendo as mãos limpas até a última mordida. Tamanho ideal para pastelarias e feirantes (13,5x16,5cm) Barreira gordura: evita vazamentos e manchas Mantém as mãos do cliente limpas até a última mordida 100% papel, sem plástico, próprio para contato com alimentos Agrega valor ao seu negócio e à experiência do cliente Produto Intercarta – referência em embalagens para alimentos Sobre a Intercarta A Intercarta é referência em embalagens alimentícias há mais de 30 anos, com produtos de alta qualidade e compromisso com o seu negócio. Invista em quem entende de alimentos e de mercado.', 114.5, 72.34, NULL, 'Stationery > Gift & Wrapping > Others', 'https://cf.shopee.com.br/file/sg-11134201-821g9-mgmrwosk1dsbed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F886490360%2F58250296969', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
