INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7567737503', 'Piercing de Nariz Nostril Prata 925', 'Itens inclusos: - Piercing de nariz em prata 925 com zircônia tamanho 1,50mm - Termo de Garantia da Prata 925 Esta linda peça, fabricada em Prata legítima, teor 925, além de linda trás a simplicidade e a elegância da beleza feminina. A Prata com teor 925, é o metal mais precioso, depois do ouro. Sua legitimidade pode ser confirmada através de sua marcação nas peças e pelo certificado de garantia que oferecemos. Garantimos a autenticidade de nossos produtos. Compre e tenha certeza de receber uma jóia com duração para o resto da vida. A prata 925 é um material que tem garantia e durabilidade permanente, assim como o ouro 18k. Nossas jóias tem certificado de autenticidade reconhecidos no mundo todo, você pode levar em qualquer joalheria para efetuar os testes e comprovar a autenticidade das mesmas. Havendo dúvidas, não hesite em perguntar por favor! Será um prazer atendê-lo. Acompanha certificado que garante teor 925 do produto.', 29.9, 28.8, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd3m-lvdk0p1gf2xpc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F7567737503', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
