INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23791103838', 'Debulhador Descascador Para Espiga De Milho Manual Cortador Cozido para Cozinha Duhome', 'Debulhador Manual de Milho com Lâmina em Aço Inox Facilite o preparo das suas receitas com este debulhador manual de milho. Desenvolvido para remover os grãos da espiga de forma rápida e prática, possui lâmina interna em aço inox que proporciona um corte eficiente, reduzindo o esforço e evitando desperdícios. Seu formato compacto oferece uma pegada confortável e segura, sendo ideal para preparar pamonha, curau, bolos, saladas, sopas, refogados e diversas outras receitas. Características: Lâmina interna em aço inox resistente Remove os grãos com rapidez e praticidade Fácil de usar e limpar Material leve e resistente Design compacto e ergonômico Ideal para uso doméstico Especificações: Material: Plástico resistente e aço inox Diâmetro: Aproximadamente 7 cm Altura: Aproximadamente 4,5 cm Diâmetro da lâmina: Aproximadamente 3,5 cm.', 22.9, 12.9, NULL, 'Home & Living > Kitchenware > Graters, Peelers & Cutters', 'https://cf.shopee.com.br/file/br-11134207-820l9-mq7q1tj0ulfkc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F23791103838', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15140378085', 'Kit 6 Marca Texto Apagável 6 Cores Papelaria Material Escolar Marcador Neon Volta as Aulas Neon', 'O Marca Texto Apagável 6 Cores Neon Sem Apagar O Texto Vmp é o produto perfeito para destacar suas anotações e textos importantes. Com seu corpo de plástico resistente e altura de 15 cm, ele é durável e fácil de manusear. Sua tinta à base de água garante uma aplicação suave e sem borrões, enquanto sua ponta plana proporciona traços médios precisos. Com 6 cores neon vibrantes, você pode dar vida aos seus estudos, desenhos e materiais escolares. Embalado em blister, é fácil de armazenar e transportar. Recomendado para uso em papel, o Marca Texto Apagável 6 Cores Neon Sem Apagar O Texto Vmp é a escolha ideal para uma experiência de marcação de texto única e de alta qualidade.', 26.99, 14.16, NULL, 'Stationery > Writing & Correction > Highlighters', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mht0jp1zgxdt3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F15140378085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
