INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51612113613', 'Boneco Funko Pop! Disney Hércules - Meg com Flor', 'Adicione romance e personalidade à sua coleção com o Boneco Funko Pop! Meg com Flor, inspirado na personagem mais carismática do clássico da Disney. Nesta versão encantadora, Meg aparece segurando uma flor, capturando toda a leveza, atitude e charme que marcaram sua história ao lado de Hércules. Com aproximadamente 11 centímetros de altura e acabamento detalhado, este Funko Pop! é perfeito para fãs da Disney e colecionadores que desejam um item elegante, expressivo e cheio de emoção para destacar seu display.', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824gq-mpdvq00dpqmaeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F51612113613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202398172', 'Colchão de Espuma D60 Double Face Guarda Costas Comfort Force Probel Casal 138cm', 'Procura um colchão firme com o melhor suporte? O Comfort Force da Probel, conta com espuma D60 que oferece alta densidade e sustentação estável, ideal para quem busca noites firmeza e suporte. Precisa de durabilidade real? O sistema Double Face permite virar o colchão e prolonga sua vida útil, mantendo suporte para até 120kg por pessoa. Especificações Técnicas do Colchão: - Marca: Probel; - Exclusivo Lucas Home; - Tipo: Espuma D60; - Tipo de conforto: Firme; - Proteções: Antiácaro, Antialérgico, Antifungo, Antimofo; - Tampo: Bordado; - Sistema Double Face: Permite virar e girar(maior durabilidade); - Peso máximo recomendado: até 120kg (por pessoa); - Garantia: 3 meses; - Dimensões (larg. x comp. x alt.) 138x188x22cm. Importante: As cores podem variar conforme a tela; Não oferecemos montagem; recomendamos profissionais qualificados. Confira as dimensões para transporte em elevadores e passagens. Não transportamos por meios especiais. Por se tratar de um produto de uso íntimo e pessoal, só aceitaremos devoluções por arrependimento apenas se a embalagem do produto não for violada.', 2087.7, 1186.7, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820m6-mlnnnw573qiv02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208859337%2F58202398172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
