INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198316396', 'Kit Embreagem Fiesta/ka/courier Zetec 2000/2013', 'KIT DE EMBREAGEM (DISCO E PLATÔ) Código: MB2A7540AA Marca: Ford / Motorcraft (peça genuína) Conteúdo do kit: 1 disco + 1 platô Não acompanha: rolamento/atuador Aplicações Ka 2009 a 2013 Fiesta Rocam 1999 a 2014 Ka 1997 a 2007 Courier Zetec 1.4 Para 100% de certeza, informe o chassi (VIN) ou consulte o manual do veículo. Sobre a peça Conjunto original com encaixe preciso e durabilidade no padrão de fábrica, garantindo acoplamento correto e trocas mais suaves. Quem vende GAMBATTO FORD — Concessionária Ford. Apenas produtos novos e originais, com procedência garantida e suporte técnico especializado. Envio rápido Em estoque: pedidos confirmados até 11h59 são despachados no mesmo dia útil. Demais pedidos seguem no próximo dia útil. Garantia e devolução 90 dias contra defeitos de fabricação (mediante diagnóstico técnico). Devolução somente com produto e embalagem intactos. Instalação inadequada pode anular a garantia.', 480.0, 480.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-824h5-mf8m0l8xm7ez03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1630931801%2F20198316396', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200194272', 'Martelo Unha 27mm Vonder com Cabo de Fibra Emborrachado', 'Martelo Unha 27mm Vonder com Cabo de Fibra Emborrachado Projetado para máxima performance e conforto, o Martelo Unha 27mm da Vonder (Ref. 3589027000) é a ferramenta ideal para carpinteiros, marceneiros e profissionais da construção. Sua cabeça de 27mm, feita em aço forjado com acabamento polido, oferece a resistência necessária para pregar com precisão e a durabilidade para arrancar pregos sem esforço. O grande diferencial deste martelo é seu cabo de fibra de vidro de alta resistência, que absorve melhor os impactos e vibrações do que a madeira, reduzindo a fadiga do operador. Além disso, possui uma empunhadura ergonômica em borracha termoplástica, garantindo uma pegada (grip) firme, segura e confortável, mesmo durante o uso contínuo. - Principais Benefícios: * Alta Resistência: Cabeça de 27mm em aço forjado para máxima durabilidade. * Conforto Superior: Cabo em fibra de vidro que absorve vibrações e reduz o cansaço. * Pegada Segura: Empunhadura em borracha termoplástica (emborrachada) que evita o deslizamento. * Leveza e Equilíbrio: Mais leve e resistente que os cabos de madeira tradicionais. * Acabamento Polido: Proteção extra contra oxidação e corrosão na cabeça do martelo. - Características Técnicas * Produto: Martelo Unha * Marca: VONDER * Referência: 35.89.027.000 * Medida Nominal (Diâmetro da Cabeça): 27 mm * Material da Cabeça: Aço Forjado * Acabamento da Cabeça: Polido * Material do Cabo: Fibra de Vidro * Material da Empunhadura: Borracha Termoplástica (TPR) * Comprimento Aproximado (Total): 315 mm * Largura da Cabeça: 138,0 mm * Massa Aproximada (Peso): 0,69 kg Informações de Garantia Garantia: 90 dias (Garantia legal) contra defeitos de fabricação.', 56.65, 56.65, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821fy-mgh0bx1pqhhmbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984366979%2F58200194272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
