INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13019901710', 'Pulseira borboleta prata 925 delicada', 'Pulseira borboleta prata 925 delicada Comprimento: 19cmMaterial: Prata 925 (acompanha certificado)Garantimos a autenticidade de nossos produtos. Compre e tenha certeza de receber uma jóia com duração para o resto da vida. A prata 925 é um material que tem garantia e durabilidade permanente, assim como o ouro 18k. Nossas jóias tem certificado de autenticidade reconhecidos no mundo todo, você pode levar em qualquer joalheria para efetuar os testes e comprovar a autenticidade das mesmas. Havendo dúvidas, não hesite em perguntar por favor! Será um prazer atendê-lo.Acompanha certificado que garante teor 925 do produto.', 79.99, 55.5, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/sg-11134201-821dt-mh9fpw4pyeq3b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F13019901710', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794934996', 'Refrigerante Sprite Lemon Fresh Pet', 'Sendo um refrigerante de limão equilibrado, refrescante e com um toque a mais de sabor, Sprite Lemon Fresh 510ml Pet é uma opção mais do que perfeita para quem busca uma combinação exclusiva do gás e notas cítricas da fruta. Esta bebida proporciona uma sensação revigorante a cada gole, tornando-se ideal para acompanhar qualquer momento do seu dia. Leve e sem adição de açúcar Uma das grandes vantagens de Sprite Lemon é a sua fórmula sem adição de açúcar, garantindo um sabor autêntico e balanceado sem abrir mão da leveza. Além disso, a sua embalagem de 510ml tem o tamanho perfeito para manter o frescor e garantir a tranquilidade de levar para todo e qualquer lugar que você precisar ir. O que esse refrigerante zero tem de diferente? Sabor refrescante de limão com notas cítricas ainda mais marcantes; Sem adição de açúcar, perfeito para quem não quer consumir calorias; Embalagem prática de 510ml, ideal para tomar sozinho. Refrescância instantânea para qualquer hora do dia.', 3.99, 3.99, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-825a4-mqnekjg6p14xde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F23794934996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
