INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7744334684', 'Inflador Compressor 110v Bomba Balões Bexigas 2 Bicos Festas', 'Design leve, inteligente, portátil e prático de utilizar, para festas e eventos, atividades promocionais e publicidade. Potência de 600W, você consegue encher até 2 balões ao mesmo tempo em aproximadamente 2 SEGUNDOS! Tem um compartimento para guardar a tomada. Possui dois modos de operação: - Swith on/off que aciona os dois bocais ao mesmo tempo. - Touch ON (a bomba liga ao encostar a bexiga no pino e desliga quando retira). - Seus bocais foram desenvolvidos para tornar a operação muito mais fácil, basta encaixar o balão e inflá-lo. - Bocal azul funciona individualmente ao ser pressionado. - Potente, de baixo ruído e pés em borracha, para se fixar melhor à superfície. - Ruído <95DB - Voltagem: 110V. Cor Disponível: APENAS ROSA. Dimensões: Altura: 16 cm Largura: 12 cm Comprimento: 19,5 cm Peso: 1243g Comprimento do fio da tomada: 150 cm', 129.88, 78.5, NULL, 'Home & Living > Party Supplies > Balloons', 'https://cf.shopee.com.br/file/86e87e46ed5daebedc96b1b371690d63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F283838689%2F7744334684', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49506202870', 'Monitor 21.5 Philips Gaming Fhd Va 120hz 1ms 221v8lb3', 'O Monitor Philips 21,5” 221V8LB3 é a escolha ideal para quem busca desempenho fluido, excelente qualidade de imagem e ótimo custo-benefício para trabalho, estudos e jogos. Com taxa de atualização de 120Hz e tempo de resposta de 1ms, oferece imagens mais suaves e precisas, reduzindo borrões e atrasos em cenas rápidas. Sua tela Full HD (1920x1080) proporciona imagens nítidas e cores vibrantes, garantindo ótima experiência tanto para entretenimento quanto para produtividade. Principais CaracterísticasTela de 21,5 polegadas LED Resolução Full HD (1920 x 1080) Taxa de atualização de 120Hz Tempo de resposta de 1ms Painel com excelente nitidez e contraste Tecnologia para redução de cintilação (Flicker-Free) Modo LowBlue para menor emissão de luz azul Conexões HDMI e VGA Design moderno na cor preta Ideal para:Jogos com maior fluidez e menor atraso de imagem Escritório e home office Estudos e navegação Consumo de vídeos e streaming Além do desempenho visual, o design é elegante e compacto, facilitando a integração em qualquer ambiente, seja setup gamer ou estação de trabalho. Um monitor versátil, rápido e eficiente para quem quer qualidade e performance no dia a dia.', 899.0, 579.0, NULL, 'Computers & Accessories > Monitors', 'https://cf.shopee.com.br/file/sg-11134201-82615-mko4979yh343b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1509845472%2F49506202870', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
