INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193269560', 'Kit Pastilha Freio March Tiida Versa Sumitomo Cobreq N1426', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação NISSAN MARCH S 1.0 16V 2012 até 2014 MARCH SV 1.6 16V 2012 até 2019 TIIDA HATCHBACK 2008 até 2013 VERSA S 1.6 16V 2012 até 2014 VERSA SL 1.6 16V 2012 até 2020 VERSA SV 1.6 16V 2012 até 2020 Conteúdo Da Embalagem 4 Pastilhas de Freio Tipo de Veículo para Carros Marca A Cobreq (TMD Friction do Brasil) foi fundada em outubro de 1961, na cidade de São Paulo. Fabricando pastilhas de freio desde 1969 a Cobreq foi a pioneira em fabricação de pastilhas de freio no Brasil. Uma empresa comprometida em trabalhar com seus clientes, a Cobreq fornece soluções de materiais de atrito adequados para cada finalidade, atendendo o mais alto nível de qualidade da indústria. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia - 3 meses Imagem meramente ilustrativa Valor referente ao kit Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 Antes de realizar a compra, verifique o modelo da pastilha em seu veículo e compare com o modelo do desenho técnico na imagem do anúncio. Código do Fabricante N-1426 Posição Dianteiro Sistema Sumitomo', 147.16, 147.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7rccl-lsmuochc9l9nda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fsh