INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9053827197', 'Encordoamento Earthwood 80/20 Violão 011 Ernie Ball P02004', 'Olá, seja bem-vindo à HGZ Music Store Está em busca de um encordoamento para Violão, 011 Light, para seu tão amado instrumento? A HGZ Music Store traz o Encordoamento Ernie Ball Earthwood Bronze 80/20 para atender sua necessidade! As cordas para Violão Aço mais populares, fornecem um toque agradável, com um som nítido, feitas com fios 80% de cobre e 20% de zinco, revestindo um fio hexagonal de Aço Estanhado. Encordoamentos Originais adquiridos pela importadora oficial da Ernie Ball no Brasil, Izzo Instrumentos Musicais. Tipos de Instrumento onde se pode utilizar: Violão para Cordas de Aço de 6 Cordas Calibre da Cordas (Bitola/Espessura): 1 - Mi .011 2 - Si .015 3 - Sol .022 4 - Ré .030 5 - Lá .042 6 - Mi .052 Características do Produto: Materiais: Aço Carbono Temperado e Estanhado, Aço Niquelado, Aço Cor: Prateada O que você está comprando: 1 Encordoamento Earthwood Bronze 80/20 para Violão 011 P02004 Somos a HGZ Music Store, uma empresa totalmente focada em e-commerce no ramo de Instrumentos Musicais, sempre oferecendo as melhores marcas de equipamentos do mercado e com a devida expertise ao implementa-los ao nosso catálogo. Sua experiência será a de uma compra segura e garantida pelas melhores tecnologias de operação do mercado e entrega rápida! Caso tenha ficado alguma dúvida, nossa equipe estará pronta para te atender! HGZ Music Store', 89.9, 79.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7qvd6-lj0avrd129q9bc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340675874%2F9053827197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
