INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593490032', 'Led Drl T20 Luz Diurna Nova Strada 2021 6000k Sem Erro', 'Par de Lâmpada LED T20 2 Polos SMD-4014/3030 12V Branco6000K 23 LEDs SMD Funciona para DRL, luzes de condução diurna, luzes de sinal de direção, luzes reversas , lâmpadas traseiras, luzes de freio e etc Chips de led de alta potência, Chip SMD 3020, que proporcionarão um padrão de feixe perfeito, alta saída de luz e baixo consumo de energia boa dissipação de calor e alto brilho, vantagens de estabilidade e durabilidade superiores que as lâmpadas comuns. Características: - Iluminação completa de 360° graus - 300% mais brilhante que o halogênio - +60% Melhora a Eficiência da Luz - Resistente a vibrações - Dura até 8x Mais - Despolarizado - Encaixe: T20 7443 - 2 POLOS - Tonalidade (K): 6000K - Voltagem: 12V - IP RATE: IP65 - Para Aplicação no DRL e Luzes de Freio - Qualidade Superior e Longa Vida Útil - Dimensões Aproximadas (C x L x A): 15x9x1cm Modelo Disponível: - SMD-4014/3030 Cores Disponíveis: - Branco Conteúdo da Embalagem: • 01 Par de Lâmpadas LED Importante: - Garantia de 3 Meses. - Valor do Par. Imagens Meramente Ilustrativas. Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 121.99, 121.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1pm8eksm2zuc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397441974%2F23593490032', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598987035', 'Chicote da Resistência do Ar Condicionado - FIAT/VW', 'Chicote da Resistência do Ar Condicionado - O Chicote da Resistência do Ar Condicionado é projetado para garantir a comunicação eficiente entre o sistema de controle e a resistência do ar condicionado. Ele permite o ajuste da velocidade do ventilador, proporcionando conforto térmico e contribuindo para o funcionamento adequado do sistema de climatização. Especificações e Aplicações: Aplicação: Veículos das marcas e com sistema de ar condicionado com controle de velocidade do ventilador. ATENÇÃO -Os conectores são muito parecidos, as vezes com algum pequeno detalhe diferente, como uma trava ou ranhura. Por isso compare o seu com as fotos antes de fazer a compra. -Pode Haver outras aplicações não descritas acima. 90 DIAS DE GARANTIA.', 30.5, 30.5, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-824il-mfobi25xiw3z59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397441974%2F23598987035', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
