INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798895349', 'XAROPE MONIN CRANBERRY 700ML', 'O Xarope Cranberry é a escolha perfeita para dar um toque sofisticado, refrescante e levemente ácido às suas bebidas e receitas. Com sabor marcante e coloração vibrante, é ideal para a preparação de coquetéis alcoólicos e não alcoólicos, sodas italianas, mocktails, chás gelados, sucos, sobremesas e até caldas para finalização. Sua formulação foi desenvolvida para oferecer equilíbrio entre acidez e doçura, garantindo versatilidade e performance em diferentes aplicações. Com embalagem prática de 700ml, é fácil de dosar e armazenar, sendo um ingrediente essencial para bares, cafeterias, confeitarias e uso doméstico.', 76.99, 59.99, NULL, 'Food & Beverages > Beverages > Cordial & Syrups', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mek1pj7lw5c056', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23798895349', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
