INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28874993913', '2 - Hydrox Fast 500m Protetor Verniz Automotivo Hidro Repelente Vonixx', '2- HYDROX FAST 500ML VONIXX HYDROX FAST é um revolucionário coating cerâmico hidrorreativo de alta tecnologia. Ele é ativado através da água, sem necessidade de toque. Proporciona uma incrível proteção de até 10 meses na pintura, deixando o toque liso, aumentando significativamente o brilho e protegendo contra a ação do tempo. Também pode ser aplicado em vidros para melhorar a hidrorrepelência. MODO DE USO: 1- Lave bem o veículo. 2- Com o carro ainda molhado, pulverize o produto sobre toda a pintura, sempre fria, sem deixar o produto secar na superfície. 3- Enxágue imediatamente utilizando uma lavadora de alta pressão para ativar o produto e observe o efeito de hidrorrepelência imediato. 4- Seque o veículo. Garantia do vendedor: 3 meses', 93.99, 93.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5so3y6q6y6dda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F28874993913', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
