INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4763956569', 'Playmobil - Piratas Galácticos Com Helicóptero', 'Os Pirates Galácticos estão atacando com seu helicóptero! "Protejam-se rapidamente", chama o policial espacial. Enquanto ele está prestes a fugir para seu drone, dois projéteis já estão voando por ele. Ufa, isso foi muito perto. Mas os piratas espaciais já o alvejaram novamente e estão se preparando para atirar. O policial reage rapidamente e atira diretamente nos dispositivos de navegação vermelhos. O helicóptero imediatamente se torna incapaz de voar e afunda no chão. Os dois piratas rastejam para fora da aeronave e fogem. Eles vão escapar do policial espacial? O conjunto de jogos contém três figuras PLAYMOBIL, um policial espacial e dois piratas espaciais, um helicóptero com dois lançadores de foguetes e rotores de ataque rotativos, Figuras: 2 Piratas Galacticos; 1 Acessórios Galáctico Policial: 1 helicóptero; 1 braço de apoio; 2 balas de canhão; 1 drone policial Galactico; 2 pequenos projéteis; 1 pedra de energia; 1 cristal; 2 armas pretas; 1 arma branca; 1 unidade de controle; 1 capacete; 1 fone de ouvido com microfone boom; 1 par de acessórios de braço;', 699.99, 657.99, NULL, 'Mom & Baby > Toys > Block Toys', 'https://cf.shopee.com.br/file/72c735267768f5a6f20b51b656e1bf16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F4763956569', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20531585161', 'Harry Potter - Playset Dedos de Mel com Neville e Luna', 'Descrição: Visite a Dedos de Mel com Luna Lovegood e Neville Longbottom e recrie suas cenas favoritas de Harry Potter! Este playset é perfeito para suas aventuras no Mundo Mágico. Cada boneco exclusivo de 7cm contém doces da Dedos de Mel e é posável - vire a cabeça, mova os braços e faça-os sentarem! Adicione à sua narrativa 5 acessórios! Cole os sapos de chocolate pela loja e encontre outro sapo na caixa! No balcão, compre feijão de todos os sabores e doces do pote! Características: Marca: Sunny Brinquedos Referência: 3122 Idade recomendada: A partir de 3 anos Usa Pilhas/Baterias ?: Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 19,2 x 22,6 x 8,2cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Cenário, 2 Bonecos de 7cm, 5 Acessórios, 1 Kit de Etiquetas Certificado Inmetro: REGISTRO 3502/2021 BRI-1 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 229.99, 216.19, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/2c20f8985409466e86b81123082ffd7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F20531585161', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
