INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194878005', 'Friso Renegade Porta Lateral Modelo Original Sport Altitude Longitude Willy 2023 2024 2025 2026', 'O friso lateral original Grid para o Jeep Renegade foi desenvolvido para oferecer proteção eficiente e visual alinhado ao design robusto do veículo. Produzido com material de alta resistência, ajuda a proteger as portas contra pequenos impactos, riscos e batidas do dia a dia, mantendo a integridade da pintura. Com encaixe preciso e acabamento de padrão original, o friso valoriza a estética do Renegade sem descaracterizar o modelo. A instalação é prática, sem necessidade de furação, utilizando fixação segura e durável. Cores disponíveis: Branco Polar Azul Jazz Cinza Granite Cinza Sting Gray Prata Billet Preto Carbon Ideal para quem busca proteção, durabilidade e valorização visual, mantendo o Jeep Renegade com aparência original e sofisticada.', 364.99, 364.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-8261t-mkmm4hjh03r596', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322429563%2F22194878005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
