INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299604144', 'Friso Porta Creta Platinum Nline Comfort Limited 2022 2023 2024', 'Instalação Fácil: A instalação é rápida e simples, com adesivos de alta aderência 3M que garantem um acabamento sem furos ou danos ao veículo. Proteção Extra: Evita danos à pintura lateral do seu carro, como arranhões causados por portas de outros veículos ou objetos no trânsito. Garantia : 12 Meses Benefícios: Protege a lataria do seu Creta contra impactos e riscos. Valoriza o design do seu carro, deixando-o mais imponente e estiloso. Facilidade de instalação e remoção, sem necessidade de ferramentas especiais. Adicione mais estilo e proteção ao seu Creta com o Kit Friso Portal Lateral! Ideal para quem busca qualidade, praticidade e um toque extra de sofisticação para o veículo. Não perca a chance de deixar o seu carro ainda mais exclusivo e bem protegido!', 269.9, 269.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rcc2-m6ig5xgsxhg2a7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322429563%2F20299604144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
