INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200651051', 'Pepete Vizzano com Tiras em X 6510.121.30577', 'Pepete Vizzano com Tiras em X A Pepete Vizzano com Tiras em X é confeccionada com tramas em seu cabedal. A tendência do verão 2026 traz também em sua construção tiras e um pingente metalizado. Sua palmilha macia assegura conforto para o dia a dia e o solado em borracha oferece segurança. Compre Pepete Vizzano com Tiras em X Primavera Verão 2025 Ref.: 6510.121.30577', 199.99, 160.0, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-821fo-mgwq7ajgzpjd54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1668934902%2F58200651051', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
