INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394938361', 'Bota Feminina Lana Preto', 'A Bota Feminina Lana, a escolha perfeita para quem busca o equilíbrio entre o estilo robusto do coturno e a sofisticação do couro. O cabedal em couro oferece um brilho sutil e elegância, Pensada para a mulher moderna, ela substitui os atacadores tradicionais por elásticos, que se ajustam ao formato do seu pé sem apertar, e conta com um fechamento lateral por zíper, proporcionando um calce rápido e prático. O solado de borracha tratorado leve garante aderência e segurança em diferentes superfícies, com um salto de 5 cm — a altura ideal para quem não abre mão do conforto durante todo o dia. O toque final de luxo fica por conta do detalhe "D" em metal dourado, assinatura exclusiva da linha Democrata Ela.?Especificações:Material Externo (Cabedal): CouroFechamento: Zíper lateral funcional e atacadores de elástico.Forro Interno: Têxtil macio para melhor respirabilidade.Palmilha: EspumaSolado: Borracha antiderrapante de alta durabilidade.Altura do Salto: 5 cm (estabilidade e conforto).Detalhes: Aplicação de metal dourado com a logomarca no cano.', 399.9, 399.9, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-8258b-mqop78u53ea6ee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1618027254%2F23394938361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
