INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899603154', 'KIT 02 PNEU PARTNER 175/75R14 86T HF261 HIFLY', 'Kit com 2 pneus HIFLY 175/75R14 86T HF261 Tenha mais segurança e conforto ao dirigir com o kit de 2 pneus HIFLY 175/75R14 86T HF261. Fabricado com tecnologia avançada, ele proporciona excelente estabilidade, aderência e resistência ao desgaste, sendo uma ótima opção para quem roda em vias pavimentadas. Diferenciais do produto: Maior durabilidade – Treadwear 400, oferecendo uma vida útil prolongada. Rodagem silenciosa – Baixo nível de ruído (70db), proporcionando mais conforto. Acabamento sofisticado – Laterais com letras pretas para um visual moderno. Especificações Técnicas: Marca: Hifly Aplicação: Vias Pavimentadas Índice de carga (por pneu): 86 (530kg) Índice de velocidade: T (190 km/h) Durabilidade (treadwear): 400 Aderência (traction): E Temperatura (temperature): E Eficiência: E Aderência: E Nível de ruído: 70Db Construção: Radial Tipo: Sem Câmara Desenho da banda: Assimétrico Lateral: Letras Pretas A escolha ideal para quem busca um pneu confiável, econômico e durável para o dia a dia!', 562.54, 511.91, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rasx-machjx1lejbk4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1053375354%2F19899603154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
