INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097499276', 'Violao Sc200c Ns Lh Canhoto Kit Capa Acessorios', 'A Strinberg nasceu na decada de 90 com o intuito de oferecer aos musicos uma linha de instrumentos de cordas diferenciada e com estilo proprio. Seguindo os padroes de qualidade exigidos pelo mercado americano, a marca possui em sua alma a essencia da musicalidade brasileira. Com produtos modernos e sofisticados, a Strinberg conta com uma extensa linha de instrumentos musicais como guitarras, contrabaixos, violoes e diversos acessorios. ACOMPANHA: -01 CAPA REFORCADA EM NYLON 600 -01 CABO DE 5 METROS -01 CORREIA -01 CAPOTRASTE -03 PALETAS Violao Nylon Classico Tampo: Spruce Corpo: Sapele Acabamento: Fosco (NS) Escala: Indian Laurel - 19 Trastes Braco: Nato Cavalete: Indian Laurel Frisos: Preto E Ivory Nut: 51 mm Marcacao Escala: Oval Encordoamento: Tensao Normal Tarraxas: Madreperola Cromadas Pre: SE-60', 1177.9, 1177.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rbkp-lonwnciuwgo84b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F20097499276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
