INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698450449', 'Camisa Kappa Vasco II 2025', 'A Camisa Vasco II 2025 da Kappa é a escolha perfeita para os torcedores apaixonados vestirem seu orgulho. Com design elegante e tradicional, traz o branco como cor predominante e a icônica faixa transversal preta. Confeccionada em poliéster e elastano com tecnologia no tecido, oferece conforto, leveza e respirabilidade. O escudo do clube bordado se destaca no peito. Detalhes como a frase “Sou Vascaíno” na nuca e “Jamais terá a cruz. Este é meu batismo” no interior da gola reforçam a identidade cruzmaltina. A gola em V, punhos e nuca em preto completam o visual moderno e fiel à história do Vasco.TecnologiasKOMBAT PRO SYSTEM®: Técnica autêntica que atribui uma elegância italiana ao design do produto, sustentando-se nas especificidades dos atletas profissionais.Hidroway Protection: Tecido de alta performance com absorção de umidade e secagem rápida, proporcionando melhor conforto e excelente caimento.Composição: 97% Poliéster e 03% ElastanoCor predominante: BrancoClube: Vasco da GamaModelo: TorcedorGênero: MasculinoOrigem: NacionalEscudo: BordadoManga: CurtaGola: VDimensões aproximadas (A x L):P: 70 x 51 cmM: 73 x 54 cmG: 76 x 55 cmGG: 78 x 59 cmEG (3G): 80 x 62 cmEEEG (5G): 86 x 70 cm7G: 91 x 77 cm', 245.9, 245.9, NULL, 'Men Clothes > Tops > Shirts', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfmitx37llog9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F22698450449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
