INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13467827473', 'Creme de Pentear Babosa 800g Probelle probelle PROMOÇÃO', 'Creme de pentear Babosa Creme para pentear Babosa de altíssima performance, especialmente desenvolvido para aumentar o volume com nutri reparação. Finalização de altíssimo desempenho. Desembaraça, dá brilho e volume com ação anti radicais livres. Fórmula sofisticada com matérias primas de baixo peso molecular que penetram com maior facilidade no córtex com resultado de longa duração. Volume com aumento da elasticidade e brilho com toque mágico. Ativos: Para acabar de vez com o ressecamento dos seus fios, a Babosa é rica em diversas vitaminas (como a A, B1, B2, B3, B6, B12, B13, C e E), mais de 17 aminoácidos e 20 minerais. Imagina isso tudo nos seus cabelos. O resultado serão fios ainda mais fortes, com crescimento saudável e com aquele brilho que você sempre sonhou. Máscara: Atenção ao Cronograma Capilar, porque essa máscara é perfeita para a Hidratação dos seus fios. Nossa Máscara Volumex Babosa, vai hidratar profundamente os seus fios e devolver naturalmente as proteínas e vitaminas aos seus fios. Além disso, nossa Máscara ajudará no controle da oleosidade, fortalecendo os seus fios e estimulando o crescimento saudável.', 21.9, 19.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/0748ed08b38266732595aff35518f50f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648982173%2F13467827473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
