INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693916911', 'Cabide Plástico Adulto 40cm Preto Easy Sanremo 5 Unidades', 'Cabide Plástico Adulto Preto Easy Sanremo 40cm – 5 Unidades: ideal para organização e praticidade no seu guarda-roupa. Esse cabide leve e resistente é perfeito para diferentes tipos de roupas, como camisetas, casacos leves, blusas e vestidos com alça, suportando até 3,2 kg por unidade. Com ótima relação custo-benefício, cada cabide comporta duas peças, otimizando espaço no armário. Feito com qualidade Sanremo, oferece durabilidade e eficiência para organizar suas roupas de forma prática e segura. Garanta já o seu cabide Sanremo e melhore a organização do seu closet com um toque de economia e estilo!', 49.9, 29.9, NULL, 'Home & Living > Home Organizers > Hangers & Pegs', 'https://cf.shopee.com.br/file/sg-11134201-7renk-m8m0wt18rgyx13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22693916911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
