INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494086700', 'Fonte Carregador Jfa 120a Bob Slim Bivolt Cor Preto', 'Fonte Carregador Jfa 120a Bob Slim Bivolt Cor Preto A Bob Storm é um recurso utilizado em projetos que não exigem um número tão alto de funcionalidades, é o caso das Caixas Bob. Foi pensando nisso que a JFA criou a Bob Storm uma fonte específica para você que quer sobretudo, simplificar o seu projeto de sua caixa bob. Seu principal diferencial é que o seu uso dispensa a necessidade de uma bateria para funcionar, mantendo a mesma performance. Veja suas principais características. • Função Storm que indica que a fonte está operando em seu mais alto potencial com tensão de saída para 15V. • Design harmônico que permite a adaptação da Bob Storm em projetos de forma compacta. Especificações Técnicas • Entrada: 90 a 140Vac / 170 a 240Vac (Bi-volt automático) • Função BOB-STORM: - Potência nominal 70 Amperes - Potência dinâmica 120 Amperes / 2 seg - Potência de pico 180 Amperes • Tensão de saída ajustável: 12 a 15V • Smart cooler - Sistema de ventilação inteligente: Controle dinâmico por PWM • Proteções: Excesso de carga / Curto na saída / Temperatura • Dimensões L x A x P (mm): 259 x 151 x 58 • Peso: 1,440 CONTEÚDO DA EMBALAGEM: - 01 Fonte Carregador Jfa 120a Bob Slim Bivolt Cor Preto', 459.71, 419.98, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mao37m4s9fy14b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F955465113%2F22494086700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
