INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12239964402', 'CALCINHA BOXER TRIFIL 4045', 'Características: Calcinha boxer, deixa o bumbum perfeito. Modelagem ampla cobertura, mais suporte e segurança. Cós e bainha sem costura, não apertam e não marcam. Construção diferenciada na parte de trás que modela levemente e valoriza o bumbum. Modo de Lavagem: Somente lavagem manual. Não usar alvejante à base de cloro. Proibido usar secadora. Não passar. Não limpar à seco. Composição: 92% Poliamida, 06% Elastano e 02% Algodão.', 67.0, 67.0, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/sg-11134201-22100-0y30wbfl25iv18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F12239964402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094431425', 'Kit 3 Meias Performance Running Lupo Cano Curto Ref 3276-002', 'PRINCIPAIS BENEFÍCIOS: • Tecnologia Dry: Alta tecnologia na absorção de suor, proporcionando muito mais conforto durante o exercício. • Proteção Reforçada: Atoalhada com felpa de proteção na sola e em regiões de maior impacto. • Estabilidade Anatômica: Possui faixa de compressão no peito do pé para maior estabilidade durante o movimento. • Conforto Térmico: Tecido com textura especial de ventilação que auxilia na regulação da temperatura. • Design Inteligente: Modelo com pé direito e pé esquerdo definidos, além de puxadores traseiro e frontal que auxiliam na hora de vestir. ESPECIFICAÇÕES TÉCNICAS: • Marca: Lupo (100% Original) • Modelo: Performance Running (Ref. 3276-002) • Cano: Curto • Composição Premium: 97% Poliamida e 3% Elastano. GUIA DE TAMANHOS: • 33-36 | 37-40 | 41-44 CONTEÚDO DA EMBALAGEM: • 01 Kit contendo 3 pares de meias Performance Running Lupo (escolha a combinação de cores nas variações do anúncio).', 93.5, 93.5, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-824g1-mf1aar1t6xhq43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F23094431425', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392961043', 'Kit com 3 Meias Calças Fio 20 Europeu Trifil 6308 G', 'Características: Meia calça Modelo Europeu Efeito transparente fio 20 Confeccionada em microfibra, com toque suave e confortável Ideal para o dia a dia Cintura em tecido duplo com elástico canelado, que proporciona ajuste perfeito ao corpo Possui calcanhares e tornozelos sem costura que não irritam a pele Com demarcação de ponteira e de calça Cores: Preto: Todas preto Bege: Todas bege Composição: 98% Poliamida e 02% Elastano', 69.5, 69.5, NULL, 'Women Clothes > Socks & Stockings > Pantyhose', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-lu6cz228yv9n90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F22392961043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194060192', 'Meia Social Lupo 1795-004', 'Características: Meia Social Masculina Sensação de frescor para os seus pés A tecnologia modal assegura uma peça extremamente sedosa e macia ao toque Possui excelente absorção ao suor garantindo conforto térmico e respirabilidade da pele Com formato anatômico, a meia modal estende ao pé trazendo mais proteção e fixação Punho canelado garante melhor ajuste. Calcanhar verdadeiro. Cano: Longo Composição: 78% Modal, 20% Poliamida e 02% Elastano', 52.3, 52.3, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7raue-ma2x02t21i8h84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F22194060192', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499572053', 'Fardo 6 Unidades Kombucha Em Lata 350 ML Com Gás - Samurai Nutrition', 'PRODUTO ORGÂNICO SAIBA MAIS SOBRE A KOMBUCHA Probióticos Naturais: A Kombucha é rica em probióticos, que são micro-organismos benéficos para o sistema digestivo. Eles ajudam a equilibrar a flora intestinal, promovendo uma digestão saudável e fortalecendo o sistema imunológico. Alternativa Saudável: Em vez de optar por refrigerantes tradicionais carregados de açúcar e produtos químicos, escolher a Kombucha da Samurai Nutrition oferece uma alternativa saudável, pois não contém aditivos prejudiciais à saúde. Versatilidade de Armazenamento: A tecnologia de shelf life permite que você armazene esta Kombucha por até 12 meses sem a necessidade de refrigeração. Isso a torna perfeita para levar em movimento, para viagens e para ter sempre à mão quando precisar de uma bebida saudável e saborosa. ------------------------------- Açaí com guaraná ------------------------------- Ingredientes: Água, Açúcar 5,8%*, Chá Verde (Camellia sinensis), Chá Mate (Ilex paraguariensis), Aroma Natural de Açaí e Aroma Natural de Guaraná, Cultura de Kombucha (SCOBY), Edulcorante Stévia: 0,02 gramas por lata de 350mL. -------------------------------- Abacaxi com menta -------------------------------- Ingredientes: Água, Açúcar 5,8%*, Chá Verde (Camellia sinensis), Chá Mate (Ilex paraguariensis), Aroma Natural de Abacaxi e Aroma Natural de Menta,Cultura de Kombucha (SCOBY), Edulcorante Stévia: 0,02 gramas por lata de 350mL.', 99.9, 69.9, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4agwfexll4x56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F433531074%2F19499572053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19597432490', 'Kit Capa Protecao Correia Dentada Prisma 1.0/1.4 2007/2012 - 68009 - 106056', 'Kit Capa Protecao Correia Dentada Prisma 1.0/1.4 2007/2012 MOTOR 1.0/1.4 8V O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria. O KIT pode variar conforme o modelo do veiculo, vem: Capa Interna;e Capa Externa. (Superior/Inferior).', 58.55, 58.55, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822zt-moflkj8vtrls24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19597432490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792971448', 'Válvula Equalizadora Gm Corsa 2002 a 2015 - 203035 - 629', 'Válvula Equalizadora Gm Corsa 2002 a 2015 203035 629 (HATCH/SEDAN) - (RODA TRASEIRA) (SEM ABS) (30 BAR) (E10/S10) (SISTEMA ATE) Limitar a pressão dos freios nas rodas traseiras._x000D_ Aplicação: Normalmente é instalada no cilindro mestre, mas pode estar na linha do freio traseiro._x000D_ Funcionamento: É acionada sempre que recebe uma pressão de óleo maior que sua pressão de corte, evitando assim o travamento das rodas traseiras._x000D_ Características: Fabricadas em alumínio com tratamento superficial por anodização e componentes em aço inox.', 51.61, 51.61, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-823py-moyai9eqq5fv2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22792971448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42324769612', 'Sandália Feminina Domidona Rasteira de Dedo Strass Brilho Bico Quadrado', 'A Sandália Rasteira Domidona Bico Quadrado “Naked Sandals” é a tradução de sofisticação minimalista. Inspirada nas tendências internacionais, traz tiras finas e delicadas que criam o efeito de sandália quase invisível, realçando o charme natural de cada look. Disponível em cores versáteis preto, off white, caramelo e dourado –, combina com produções sofisticadas para festas, casamentos na praia ou jantares de verão. Ideal para mulheres que buscam elegância leve e feminina, com um toque de luxo discreto e atemporal. Cores disponíveis (Sempre seguir a cor original da foto do produto): Preto Caramelo Off White Dourado Especificações Técnicas • Tipo de produto: Rasteirinha • Material externo: Napa Sintética Madri • Material interno: Poliuretano • Solado: Microgel • Peso médio do produto: 344 g • Tipo de salto: Rasteira • Altura do salto: 1.0 cm • Fechamento: Calce fácil, sem fechamento • Numeração: Enviada conforme seleção de compra • Embalagem: Cada par é enviado em caixa individual Medidas da Palmilha • 34 — 22,9 cm • 35 — 23,5 cm • 36 — 24,2 cm • 37 — 24,9 cm • 38 — 25,4 cm • 39 — 26,2 cm • 40 — 26,9 cm Garantia do vendedor: 90 dias', 109.9, 29.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfy9szfp6bcw98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318538641%2F42324769612', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398005343', 'Correia Dentada Peugeot 106 1991 a 2003 - 163975 - CT718', 'Correia Dentada Peugeot 106 1991 a 2003 163975 CT718 MOTOR 1.0 (104 DENTES) (CVA) A correia dentada é a responsável por manter ligado o eixo-comando de válvulas ao virabrequim do motor. Ela também faz com que ambos se sincronizem. Outra função importante executada pela correia dentada é a de fazer com que as válvulas de admissão e de escapamento se fechem e se abram no momento certo. A manutenção deve ser feita ao menos de seis em seis meses, ou então a cada 10 mil km rodados. Essa quilometragem varia de modelo para modelo.', 72.03, 72.03, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmq-lms1m5gqvqg98f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23398005343', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41929206531', 'Protetor Facial Com Cinto Proteção Sustentação Para Roçadeira Kit Operador Compatível Todas Marcas', 'Kit Proteção para Roçadeira – Protetor Facial Tela de Aço + Cinto Duplo de Ombro Trabalhe com mais segurança, conforto e eficiência utilizando este kit completo para operadores de roçadeiras. O conjunto inclui protetor facial com tela de aço e cinto duplo de ombro, oferecendo proteção contra detritos e melhor distribuição de peso durante o uso da ferramenta. Ideal para quem trabalha com roçadeiras, motosserras, jardinagem, corte de grama ou limpeza de terrenos, garantindo maior ergonomia e proteção durante longos períodos de trabalho. Protetor Facial com Tela de Aço: Equipamento desenvolvido para proteger o rosto contra pedras, galhos, grama e detritos gerados durante o uso de roçadeiras ou motosserras. Possui suporte com catraca, formado por coroa e carneira em material plástico resistente, permitindo ajuste rápido e confortável na cabeça. A tela de aço resistente oferece excelente proteção contra impactos, com aprovação conforme norma ANSI Z87, proporcionando segurança durante o trabalho. Características: Suporte facial com catraca para ajuste de tamanho Tela de aço resistente fixada à coroa por pinos plásticos Tamanho da malha: 40 x 20 cm Peso aproximado: 220 g Material: Metal e plástico Produto isento de C.A. (não classificado como EPI pelo Ministério do Trabalho) Cinto Duplo para Roçadeira: Projetado para proporcionar maior conforto e ergonomia, o cinto de ombro duplo distribui o peso da roçadeira de forma equilibrada, reduzindo o esforço nos ombros e nas costas. Fabricado em nylon resistente com apoio macio, garante durabilidade e conforto mesmo em uso prolongado. Características: Material: Nylon resistente com apoio macio Detalhes em plástico reforçado Design ergonômico que distribui o peso da ferramenta Compatível com diversas marcas como: Stihl, Husqvarna, Toyama, Nakasaki, Tekna, Gharten, FortG, Carbon, Fak, Vulcan e outras. Áreas de Utilização: Operadores de roçadeira Motosserristas Cortadores de cana Serviços de jardinagem Corte de árvores e gramas Limpeza de terrenos Conteúdo da Embalagem 1x Protetor facial com tela de aço 1x Cinto duplo para roçadeira Garantia do vendedor: 3 meses', 99.0, 73.22, NULL, 'Home & Living > Gardening > Lawn Mowers', 'https://cf.shopee.com.br/file/br-11134207-820lj-mlpat4ym6vpj88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177369665%2F41929206531', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897684225', 'Bebê Reborn Menino Realista Original de Silicone Pode Dar Banho', 'Resgate seu CUPOM de FRETE GRÁTIS para Lojas Oficiais e finalize sua compra! 👶✨ Bebê Reborn Menino e Meninas – Adora Reborn ✨👶 Sua criança merece o melhor do mundo Reborn! Encante-se com a delicadeza, o carinho e a qualidade que só a Adora Reborn oferece. 💖 Características do Bebê Reborn: Tamanho: 48 cm Peso aproximado: 1 Kg Cor dos olhos: Azuis ou Castanhos. Produzida em 100% vinil siliconado – toque macio e super realista! ______________________________________________________ 🎁 Kit simples acompanha: ✔️ 1 Roupinha completa super fofa ✔️ 1 Touquinha • Certidão de Nascimento • Manual de Cuidados ✅ 1 Mamadeira ✅ 1 Chupeta Magnetica ✅ 1 Fraldas descartáveis ______________________________________________________ 🌟 São diversos itens incríveis para tornar a brincadeira ainda mais especial, educativa e realista! 🔔 Atenção: Todos os itens que não estão listados acima são meramente ilustrativos. 💝 Não perca essa oportunidade de encantar sua criança com a Adora Reborn! 💝Pode molhar Garanta já a sua! Porque quem ama, escolhe o melhor. 💕', 259.9, 99.9, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcmkdc718aiaf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F790605924%2F19897684225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
