INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57660585584', 'Escorredor de Macarrão e Alimentos em Inox 24cm - Lehaví', 'Escorredor de Massas e Alimentos Inox 24cm - Lehaví Com o escorredor para massas e alimentos da Lehaví você escorre a água de forma prática e segura, sem desperdícios ou perigo de super aquecimento do material. Facilite a sua vida na cozinha utilizando os utensílios corretos. Feito em aço inox, o produto é resistente e não possui porosidades, o que evita o acúmulo de resíduos nos orifícios do utensílio e torna a sua limpeza muito mais fácil. As alças facilitam o manuseio do produto. Dimensões: 9cm de altura x 24cm de diâmetro Características: Marca: Lehaví Referência: N1007.E01 Material: Inox Quantidade: 1 peça Imagens Ilustrativas.', 39.9, 28.9, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-822z2-moa6yqrpfaj3b9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402076848%2F57660585584', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
