INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21450046117', 'Odorizante Magest 110 Ml - Floral', 'ODORIZANTE LÍQUIDO (110 ML) MAGEST O Odorizante Magest é um dos mais procurados no mercado pelo seu agradável perfume e qualidade tanto para o seu carro quanto para os outros ambientes.MODO DE USAR: 1 - Retire o lacre de segurança;2 - Pressionar o centro da tampa até seu travamento;3 - Regular a intensidade do aroma girando o mecanismo perfurado na tampa, conforme sua conveniência;4 - Deixar agir por evaporação. Disponíveis nas Seguintes Fragâncias: "Uva" "Lavanda" "Talco" "Floral" "Citrus" "Senior"', 21.54, 21.54, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-22090-5v6acj9zuzhvb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F21450046117', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098536655', 'Kit Pilhas Alcalinas AA AAA 1,5V Avant Use 16 a 128 Unidades Alta Durabilidade para Controles e Eletrônicos', '🔋 Energia confiável e econômica para o dia a dia com alta durabilidade e opções de kits para diferentes necessidades 🔋 As Pilhas Alcalinas Avant Use AA e AAA (1,5V) são ideais para quem busca praticidade, desempenho estável e variedade de quantidades, atendendo desde uso doméstico leve até consumo mais intenso em eletrônicos. 📦 CONTEÚDO DA EMBALAGEM ✅ Kit com opções de: 16, 24, 32, 48 ou 128 pilhas ✅ Modelos disponíveis: AA (palito) e AAA ✅ Tensão: 1,5V por unidade ✅ Tipo: Pilha alcalina comum ✅ Embalagem fracionada conforme o kit escolhido 💥 BENEFÍCIOS ✔ Alta durabilidade em uso cotidiano ✔ Disponível em diferentes tamanhos de kit ✔ Compatível com diversos dispositivos eletrônicos ✔ Boa relação custo-benefício para consumo frequente ✔ Tecnologia alcalina para energia mais estável ✔ Ideal para uso doméstico, profissional e escolar ⚙️ CARACTERÍSTICAS DE FUNCIONAMENTO 🔹 Tipo: Alcalina descartável (não recarregável) 🔹 Modelos: AA e AAA (palito) 🔹 Tensão nominal: 1,5V 🔹 Indicado para aparelhos de baixo e médio consumo 🔹 Desempenho pode variar conforme o dispositivo e uso 📋 ESPECIFICAÇÕES TÉCNICAS 🔸 Marca: Avant Use 🔸 Tipo: Pilha alcalina 🔸 Formatos: AA e AAA 🔸 Voltagem: 1,5V 🔸 Kits disponíveis: 16 / 24 / 32 / 48 / 128 unidades 🔸 Uso: Geral para eletrônicos 🏠 IDEAL PARA 📍 Controles remotos 📍 Brinquedos 📍 Lanternas 📍 Relógios de parede 📍 Mouses e teclados sem fio 📍 Rádios portáteis 📍 Equipamentos eletrônicos leves e médios 🛡️ GARANTIA ✅ 12 meses contra defeitos de fabricação conforme fabricante Avant Use', 99.86, 54.9, NULL, 'Home Appliances > Batteries', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk86cg7pp0jn25', 'https://shope.ee/an_redir?origin_link