INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26239114655', 'Frigideira Turim em Alumínio Antiaderente Vermelha 16cm / 0,4L (20260/716) - Tramontina', 'A Frigideira Turim em Alumínio Antiaderente Vermelha 16cm / 0,4L (20260/716) - Tramontina,é produzida em alumínio com espessura de 1,2 milímetros e com revestimento interno e externo em antiaderente Starflon Max, ela vai garantir que os alimentos não grudem em sua superfície, facilidade na limpeza, maior durabilidade e não é prejudicial a saúde. Seu cabo em baquelite garante maior segurança durante o manuseio, pois não aquece. Uma frigideira que pode ir à máquina de lavar louças, otimizando e facilitando o seu dia! Descrição do Produto: • Corpo de alumínio com espessura de 1,2 mm que proporciona cozimento rápido e uniforme. • Revestimento interno e externo de antiaderente Starflon Max que não gruda, é fácil de limpar, mais durável e não é prejudicial à saúde, pois é livre de PFOA. • Cabo de baquelite antitérmico que oferece segurança durante o manuseio. • Pode ir à máquina de lavar louças facilitando seu dia a dia. • Pode ser utilizada nos fogões: gás, elétrico e vitrocerâmico - resistência elétrica. Referência: 20260/716. Cód. de Fábrica: 20260/716. Marca: Tramontina.', 34.25, 34.25, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-mckyf9u4febk3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F26239114655', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17583966142', 'Colete Refletivo Jaqueta Laranja PPS 08 PROTEPLUS Tamanho G', 'Características: Colete Refletivo Jaqueta Confeccionado em poliéster. Fechamento frontal por velcro. Disponível nas cores laranja e amarelo fluorescente. Aplicação: sinalização e segurança. Embalagem: unitária Referência PPS 08 Cor: Laranja Tamanho: G Código: 285,0002 EAN:7899863300029 .', 24.98, 24.98, NULL, 'Men Clothes > Occupational Attire', 'https://cf.shopee.com.br/file/cf1f9ed15c7f60220efadd7a8ff8a2a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F17583966142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392574166', 'Lente Retrovisor Convexo Para Fiat Punto Todos Lado Esquerdo', 'Lente Retrovisor Convexo Para Fiat Punto Todos Lado Esquerdo Evite multas e acidentes com nossas lentes modelo original, encaixe perfeito. Produzidas em convexo para melhor visibilidade e segurança. Compatibilidade: • Punto Todos Especificações: • Material: Prolipropileno (não trinca e ressaca); • Lente: Metalizada mais durabilidade e perfeição na projeção da imagem; • Encaixe: Específico. Conteúdo da Embalagem: • 1 - Lente Retrovisor Convexo para Fiat Punto Lado Esquerdo Garantia: • 30 dias (defeito de fabricação) Se tiver alguma dúvida a equipe Renovaccio estará pronta para lhe atender.', 44.33, 44.33, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-ln34wwabou7r40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013208711%2F23392574166', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193731002', 'Kit 2 Camisa Camiseta Agro Manga Longa Zíper Plantação Soja Colheita Café Trabalho Roça Campo Gado Boi Milho Milharal', 'KIT 2 CAMISAS AGRO GOLA ZÍPER: Camisa de Agropecuária Manga Longa com Proteção UV A camisa temática de agropecuária manga longa com proteção UV é a escolha ideal para os apaixonados pelo campo e pela vida rural. Ela combina estilo, conforto e funcionalidade para aqueles que trabalham ou têm um estilo de vida ligado à agropecuária. Feita com materiais de alta qualidade, essa camisa oferece proteção contra os raios solares negativos, graças ao seu tecido especial com fator de proteção solar (FPS). Dessa forma, você pode desfrutar das atividades ao ar livre sem se preocupar com os danos causados pelo sol. A manga longa fornece cobertura adicional, protegendo os braços do sol e também de possíveis arranhões ou insetos. Além disso, a camisa é leve e respirável, permitindo que o ar circule livremente, mantendo você fresco e confortável mesmo em dias mais quentes. O design temático de agropecuária é uma marca registrada dessa camisa. Ele apresenta estampas exclusivas, como animais de fazenda, ferramentas agrícolas e elementos da natureza, tornando-a uma peça única e apegada aos entusiastas do campo. Essa camisa é versátil e pode ser usada em diversas ocasiões. Seja para trabalhar na fazenda, participar de eventos agropecuários, fazer trilhas ou simplesmente como uma opção estilosa para o dia a dia, ela se adapta perfeitamente a diferentes ambientes e situações.', 109.9, 79.9, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6cjuib4xhgy28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F22193731002', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399188751', 'Corda Multiuso 10mm x 20m (560,0004) - Noll', 'A Corda Multiuso 10 mm x 20m (560,0004) Noll é utilizada na área náutica, na pesca, no transporte e em amarrações em geral, garantindo a segurança e eficiência em sua utilização. Pode ser muito bem utilizada para o artesanato realizando confecção de produtos, com maior facilidade e confiança. A Corda Multiuso Noll contém uma excelente capacidade para a confecção de nós e excepcional resistência contra a ruptura por flexão ou fadiga. Possui boa estabilidade e resistência a impactos e tem como maior qualidade seu baixo peso apresentando uma excelente flutuabilidade positiva. • Bitola: 10mm • Comprimento: 20m • Uso Geral • Não utilizar para elevação de cargas e pessoas Referência: 560,0004 Marca: Noll A Corda Multiuso 10mm x 20m (560,0004) Noll é utilizada na área náutica, na pesca, no transporte e em amarrações em geral, garantindo a segurança e eficiência em sua utilização. Pode ser muito bem utilizada para o artesanato realizando confecção de produtos, com maior facilidade e confiança.', 52.61, 52.61, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rcd2-lr3ef5zbvrbj8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F21399188751', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
