INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54803045205', 'Tênis Reserva Troy Camurça Cinza e Preto - Masculino', 'Estilo e sofisticação para o seu dia a dia! Tênis Reserva Troy Camurça Cinza e Preto - Masculino Marca: Reserva Gênero: Masculino Cor: Cinza e preto Cabedal: Material sintético e camurça na parte traseira e no bico Palmilha: Em EVA; moldada e removível Solado: Borracha antiderrapante Forro: Material têxtil respirável e acolchoado Lingueta: Macia e flexível Fechamento: Cadarço Indicado para: Uso diário e eventos sociais Detalhes: Recortes pelo cabedal e nome da marca na lateral e logotipo na lingueta Com design moderno e acabamento premium, o Tênis Reserva Troy é a escolha certa para quem busca elegância e conforto em cada passo. Porque investir: O cabedal em camurça e material sintético oferece visual refinado e durabilidade, enquanto a palmilha em EVA garante leveza e adaptação ao formato do pé. Ideal para compor looks casuais com um toque de sofisticação, seja no dia a dia ou em compromissos sociais. O forro respirável proporciona bem-estar prolongado, e o solado de borracha antiderrapante garante segurança ao caminhar. Conteúdo da embalagem: 1 par de Tênis Reserva Troy Camurça Cinza e Preto – Masculino', 389.99, 343.2, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-822x4-mi7db1m2qi2p94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F54803045205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
