INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250013459', 'KIT 12 UNIDADES AGUA PH7 COM GAS 500ML', 'KIT COM12 UNIDADES DA AGUA PH7 COM GAS 500ML Água pH7 com Gás 500ml" refere-se a água mineral com gás que possui um pH neutro (em torno de 7) e é engarrafada em porções de 500 ml. Por ser uma água com gás, ela é uma alternativa à água sem gás, sendo uma opção saudável por não conter açúcar ou calorias como os refrigerantes, mas ainda mantendo o gás para refrescância.', 27.99, 27.99, NULL, 'Food & Beverages > Beverages > Water', 'https://cf.shopee.com.br/file/sg-11134201-82598-mg877gry7tou46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F58250013459', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
