INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45151022181', 'Boneco Funko Pop! Fallout - Lucy MacLean', 'Aventure-se no mundo pós-apocalíptico com o Boneco Funko Pop! Lucy MacLean! Direto da série inspirada no universo do game Fallout, Lucy sai do Cofre pronta para encarar os perigos do ermo. Com aproximadamente 10 centímetros de altura, esta figura de vinil detalhada é perfeita para fãs da franquia que acompanham cada passo dessa heroína corajosa. Adicione à sua coleção um toque de ação, estratégia e sobrevivência com mais este ícone da linha POP! Television.', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824id-me0j0s2d6qdea8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F45151022181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
