INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698293446', 'Kit 4 Ralos Pia Grande 11cm Inox Cesto Com Borda Cozinha Oz', 'Distribuído Por Ismafer Ferramentas KIT 4 RALOS DE PIA CESTO / JAPONÊS GRANDE 11CM OZ O ralo de pia Oz é uma solução prática e eficiente para manter sua pia ou tanque sempre limpos. Com um design robusto, ele evita que restos de comida e outros detritos obstruam os canos, tubulações e conexões. Produzido em 100% aço inox, é resistente à ferrugem, garantindo durabilidade e preservação do seu patrimônio. Com diâmetro de 11,5 cm, é compatível com pias que possuam furo de até 7,5 cm (75 mm), sendo ideal para pias de cozinha com válvula americana de 4-1/2". VANTAGENS: - Proteção contra obstruções: Impede que restos de comida ou detritos bloqueiem os canos e tubulações, mantendo o sistema de drenagem eficiente. - Versatilidade: Além de ser ideal para pias de cozinha com válvula americana de 4-1/2", o ralo também pode ser usado em tanques, pias de banheiro, lavabos e até em cozinhas industriais. - Facilidade de manutenção: Seu design facilita a limpeza e manutenção, ajudando a manter a pia sempre limpa e livre de obstruções. FICHA TÉCNICA: - Modelo: Ralo para Pia Inox Grande - Embalagem: Cartela - Material: 100% aço inox Modelo:RP11000 Marca:o Oz SKU: KIT24657x4 Garantia: 90 Dias Fabricante Distribuído Por Ismafer Ferramentas', 65.0, 26.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcrrhfmioh6p08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F986003177%2F18698293446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699694283', 'Caixa Baú Bauleto 100 Litros Motoboy Entrega Delivery ICBRAS Resistente Premium Para Moto', 'Baú Para Moto Caixa de Entrega Motoboy 100 Litros – ICBRAS 🏍️📦✨ Ideal pra quem trabalha com entregas e precisa de segurança, praticidade e bom espaço interno no dia a dia. O baú de 100 litros atende desde pequenas até médias cargas, com estrutura reforçada e design pensado para facilitar a rotina do motoboy. Fabricado em plástico resistente, sem emendas laterais e com tampa de parede dupla, garante durabilidade e proteção da mercadoria. Visual top, funcional e pronto pra personalizar com a logomarca da sua empresa. Itens que Acompanham o Produto 📦: 1 Baú plástico para moto 100 litros 1 Kit de fixação para montagem em suporte metálico convencional (Não acompanha suporte) 1 Manual de instruções Detalhes Técnicos do Produto ⚙️: Material: Plástico reforçado de alta resistência Cor: Preto Dimensões: 50 cm x 49 cm x 56 cm Peso: 6,150 kg Capacidade: 100 litros Fechamento: Auto trava com espaço para cadeado 🔒 Tampa preparada para anexar rede elástica Compatível com suporte plástico iCbras e suportes metálicos convencionais (não acompanha suporte) Serve pra delivery? Sim, perfeito para uso diário de motoboy. Dá pra colocar cadeado? Sim, o fecho já vem preparado. É resistente? Sim, plástico reforçado e tampa dupla. Posso personalizar? Pode sim, aceita adesivos da sua empresa. IMPORTANTE: SUA SATISFAÇÃO GARANTIDA! ✔️ -----> Entrega assegurada pela Shopee com garantia', 499.9, 399.99, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/br-11134207-820m5-moscaseo0zk59a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F18699694283', NULL, NULL, '2026-07-28T02:11:31.708458+00: