INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52714651593', 'Adaptador de Áudio Banhado a Ouro 3,5 mm F para 2 RCA para Caixa de Som e Mesa de Som, Bidirecional', 'Experimente uma **qualidade de som Hi-Fi premium** com o cabo de áudio RCA RIKSOIN. Ele possui um **adaptador fêmea de 3,5 mm para macho 2RCA**, proporcionando som profissional, nítido e estável. O cabo conta com **conectores banhados a ouro** para uma conexão mais sensível e estável, garantindo integridade de sinal ideal. Construído com **condutores de cobre livre de oxigênio (OFC)**, minimiza a perda de sinal durante a transmissão, preservando cada detalhe do seu áudio. Desenvolvido para **durabilidade e flexibilidade**, o cabo é revestido com uma **jaqueta trançada de nylon** que resiste a enroscamentos, dobras, nós e vincos. Sua construção robusta o torna ideal para uso frequente. Desfrute de **ampla compatibilidade** com MP3 players, reprodutores de DVD, controladores DJ, mixers, alto-falantes e muito mais. Este cabo é uma escolha confiável para conectar seus dispositivos de áudio favoritos e elevar sua experiência de audição.', 28.6, 22.0, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/sg-11134253-8258j-mqxzpjm6htz959', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F52714651593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
