INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41065539736', 'Painel Frontal VW UP 2014 2015 2016 2017 Com Ar', 'PAINEL FRONTAL DIANTEIRO UP 2014 2015 2016 2017 COM AR DESCRIÇÃO DO PRODUTO O painel dianteiro, ou frontal, como pode ser conhecido, é um acessório automotivo que tá presente em basicamente todos os veículos, desde os tipos mais básicos até os tops de linha de cada montadora. E tem muitas funções, mas a principal é fechar a parte da frente, como se fosse uma segurança pra carroceria. ESPECIFICAÇÕES DO PRODUTO - Textura Lisa - Cor: Preto Compatível com: - UP 2014 - UP 2015 - UP 2016 - UP 2017 Especificação Técnica: • Posição DIANTEIRO • Não acompanha parafusos de fixação O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: • 01 Painel DIANTEIRO FINALIZAÇÃO As imagens representam o real estado de conservação dos produtos. Detalhes técnicos e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 689.9, 545.03, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-824i4-mdz1q5e1syrm5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F41065539736', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
