INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22028309194', 'Aspersor Estático com Base de Apoio e Ponta para Engate Rápido - Tramontina', 'Para manter seu gramado bonito e bem cuidado, você precisa irrigá-lo com frequência, não é mesmo? Com o aspersor estático com base de apoio e pontalete para engate rápido Tramontina ficou mais fácil de realizar o trabalho. A peça possui base de apoio e pontalete, proporcionando maior estabilidade ao produto. - Produto fabricado com matéria-prima de alta qualidade proporcionando uma irrigação precisa e confiável. - Com base de apoio e pontalete para fixação no terreno. - Tem uma área de cobertura de até 136 m² ou diâmetro de alcance do jato d''água de até 13,2 m - a uma pressão de 4 bar. - Sistema intercambiável que se adapta a todo o sistema de irrigação. Especificações técnicas: - O aspersor é conectado em mangueiras de: 1/2", 5/8" e 3/4" - Peso: 0,080 Kg - Produto fabricado com matéria-prima de alta qualidade proporcionando uma irrigação precisa e confiável. - Com base de apoio e pontalete para fixação no terreno. - Tem uma área de cobertura de até 136 m² ou diâmetro de alcance do jato d''água de até 13,2 m - a uma pressão de 4 bar. - Sistema intercambiável que se adapta a todo o sistema de irrigação.', 20.9, 20.9, NULL, 'Home & Living > Gardening > Irrigation Systems', 'https://cf.shopee.com.br/file/sg-11134201-23030-k11htuekm5nvab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22028309194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19398878068', 'Chave Combinada 9 mm Tramontina PRO', 'Ideal para apertar e afrouxar parafusos ou porcas com perfil quadrado ou sextavado, as chaves da Tramontina PRO são fabricadas com matéria prima que garante alta resistência e durabilidade. Para perfeito funcionamento é importante usar a chave de tamanho compatível à cabeça da porca ou parafuso. Com as chaves da Tramontina PRO, quem passa aperto é o parafuso. Cabeça usinada.Pescoço longo.Acabamento cromado.Abertura da boca calibrada.DIN 3113ISO 7738.As chaves de aperto são produzidas em aço ligado com cromo vanádio (Cr-V), e apos submetidas a testes rigorosos de torque para atender a norma DIN 1711-1.O teste de dureza é realizado em vários pontos para assegurar a resistência ao desgaste da chave durante o uso ininterrupto.Afrouxar e apertar parafusos e porcas sextavadas e quadradas.As ferramentas são produzidas e testadas conforme normas específicas. Peso: 0,05 kg Comprimento: 147 mm Largura: 7 mm Altura: 4 mm Dimensões A: 4.5 mm B: 147.5 mm C: 7.5 mm Ideal para apertar e afrouxar parafusos ou porcas com perfil quadrado ou sextavado, as chaves da Tramontina PRO são fabricadas com matéria prima que garante alta resistência e durabilidade. Para perfeito funcionamento é importante usar a chave de tamanho compatível à cabeça da porca ou parafuso. Com as chaves da Tramontina PRO, quem passa aperto é o parafuso.', 20.5, 20.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkv4fulu9wulae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F19398878068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099228170', 'Soquete Impacto-M4 3/4 x 33mm (435,0041) - Noll', 'O soquete de impacto sextavado M4 3/4 X 33mm (435,0041) - Noll é uma ferramenta essencial para aplicações que requerem torque e resistência. Projetado para trabalhar com chaves de catraca ou máquinas de impacto, este soquete oferece desempenho confiável em diversas situações. • Projetado: Para apertar e afrouxar parafusos e porcas. • Formato: Sextavado. • Bitola: 17mm • Encaixe: 3/4". Referência: 435,0027 Marca: Noll O soquete de impacto sextavado M4 3/4 X 33mm (435,0041) - Noll é uma ferramenta essencial para aplicações que requerem torque e resistência. Projetado para trabalhar com chaves de catraca ou máquinas de impacto, este soquete oferece desempenho confiável em diversas situações.', 49.11, 49.11, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcfd-lritpp25ysaf10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F18099228170', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
