INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27293120073', 'Par/Un Farol Dianteiro Polo 2023 2024 2025 2026 Full Led', 'Par/Un Farol Dianteiro Cromado Polo 2023 2024 2025 2026 Full Led DESCRIÇÃO DO PRODUTO Os faróis, sejam de luz baixa ou alta, tem como função iluminar o caminho de um veículo. Nesse sentido, é importante que os condutores saibam como fazer a regulagem correta dos faróis, pois um farol desregulado não ilumina adequadamente a rodovia ou ainda pode causar ofuscamento, perda de visão momentânea, no condutor do veículo que transita em sentido contrário. ESPECIFICAÇÕES DO PRODUTO: - Carcaça de Plástico - Full Led Compatível com: - Polo 2023 - Polo 2024 - Polo 2025 - Polo 2026 O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: •01 Farol Principal Direito •01 Farol Principal Esquerdo OU UNIDADE: •01 Farol Principal (Esquerdo ou Direito) FINALIZAÇÃO As imagens representam o real estado de conservação dos produtos. Mais detalhes e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra. Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 1239.9, 1091.12, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-820ly-mqnqbs7zb9j4de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F27293120073', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197889137', 'Baqueta com Led Liverpool 5A Luminous Series em Acrilico', 'Somos a RCK AUDIO, sua loja virtual de Instrumentos Musicais e Áudio Profissional - Há mais de 10 anos no mercado - Mais de 150.000 clientes atendidos - Todos os produtos com Nota Fiscal - Revenda autorizada oficial do produto - Criterioso processo de embalagem e expedição ; Baqueta com Led Liverpool 5A Luminous Series em Acrilico A Baqueta com LED Liverpool 5A Luminous Series em Acrílico é projetada para bateristas que desejam unir som de qualidade e impacto visual em suas apresentações. Fabricada em acrílico de alta durabilidade, essa baqueta oferece uma combinação ideal de resistência, leveza e resposta rápida, características essenciais para uma performance precisa e confortável. O modelo 5A, amplamente utilizado, oferece um equilíbrio versátil entre peso e tamanho, sendo ideal para diversos estilos musicais, desde o rock e pop até o jazz e o gospel.? Sua leveza e espessura são adequadas tanto para praticantes iniciantes quanto para bateristas profissionais, proporcionando controle e conforto nas mais variadas dinâmicas e ritmos. O grande destaque dessa baqueta é o seu sistema de LED embutido, que ilumina automaticamente com o impacto e o movimento, criando um show de luzes vibrantes e coloridas. Essa tecnologia oferece um efeito visual único, que se destaca em shows noturnos, boates, eventos e apresentações em locais de pouca iluminação, garantindo que o baterista se torne o centro das atenções. Especificações Técnicas: Linha: Luminous Series; Madeira: Acrílico; Ponta da Baqueta: Acrílico (com LED); Comprimento: 420mm; Diâmetro: 14,5mm; Acabamento: Natural.', 130.99, 130.99, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdvc-m0nhx3a0798a74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F23197889137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
