INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399407801', 'Película para Samsung Galaxy Watch 7 LTE 44mm - Hydrogel HD - Gshield', 'Aumente a resistência do seu Samsung Galaxy Watch 7 LTE 44mm com a película de Hydrogel! A Película de Hydrogel da Gshield oferece uma proteção avançada para a tela do seu Samsung Galaxy Watch 7 LTE 44mm, garantindo uma experiência duradoura e sem preocupações. Desenvolvida com a inovadora tecnologia hidro nano pet e TPU Soft Gel, essa película é resistente contra riscos indesejados. O revestimento oleofóbico da película não apenas aprimora a resistência contra arranhões, mas também reduz as marcas de digitais na tela, proporcionando uma visão clara e nítida em todos os momentos. A adaptação perfeita às extremidades curvadas do seu dispositivo assegura uma cobertura completa do visor, preservando a estética e funcionalidade do aparelho. Escolher a Película de Hydrogel Gshield é optar por um escudo de proteção sofisticado, que une tecnologia de ponta e durabilidade para manter a tela do seu celular impecável. Cuide do seu Samsung Galaxy Watch 7 LTE 44mm com estilo e confiança, investindo na excelência em proteção que só a Gshield proporciona. Clique aqui para acessar os manuais dos produtos Gshield. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: GshieldEspessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rdyr-lxs6gyp8kukqa1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F18399407801', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093508950', 'Capa Case Capinha Snap Guardian p/ Samsung Galaxy A55 Gshield – c/ Suporte Kickstand e Porta-cartões', 'Use a melhor capa para Samsung Galaxy A55 A Capa Snap Guardian da Gshield foi desenvolvida para proteger seu aparelho, com a mais alta tecnologia de absorção de impactos, garantindo extrema segurança. Fabricado com um design leve e fino, mas sem perder a segurança de proteção para seu celular. A Guardian possui um encaixe perfeito para adaptar-se totalmente ao seu aparelho; possui uma alça Kickstand, que permite utilizar o celular apoiado na horizontal, além disso, oferece um compartimento exclusivo para guardar seus cartões. ESPECIFICAÇÕES Material: Poliuretano termoplástico + PC de alta resistência - Não amarela Marca: Gshield Dimensões: Dimensões exatas do aparelho Cor: Preto Certificações: Us Military COMPATIBILIDADE Samsung Galaxy A55 ITENS INCLUSOS 1x Capa protetora GARANTIA 3 meses contra defeitos de fabricação', 98.97, 98.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7renl-m22kwbnladf974', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23093508950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
