INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29680723297', 'Pingente de Prata 925 Coração Vazado e Zircônias', 'Pingente de Prata 925 Coração Vazado e Zircônias: Delicadeza e Sofisticação O Pingente de Prata 925 Coração Vazado e Zircônias é uma joia romântica e elegante, perfeita para quem busca um acessório sofisticado e cheio de significado. Seu design delicado combina o brilho das zircônias com a leveza do coração vazado, tornando essa peça ideal para diversas ocasiões. Especificações do Pingente Tamanho: 1,2cm x 1,5mm Tamanho das Zircônias: 0,8mm Peso: 1,08g Material: Prata 925 Destaques do Pingente Design vazado em formato de coração, simbolizando amor e leveza. Zircônias brilhantes que proporcionam um toque sofisticado. Prata 925 de alta qualidade, garantindo resistência e durabilidade. Romantismo e Elegância em um Único Acessório O Pingente de Prata 925 Coração Vazado e Zircônias é uma peça encantadora que transmite sofisticação e sentimento. Seja para presentear alguém especial ou para compor um look delicado e romântico, essa joia se destaca pelo seu brilho sutil e design moderno. Cuidados com a Joia Evite contato com produtos químicos para preservar o brilho da prata e das zircônias. Guarde em um local seco e seguro para evitar oxidação e arranhões. Limpe regularmente com uma flanela macia para manter sua beleza original. Encante-se com a Beleza do Coração O Pingente de Prata 925 Coração Vazado e Zircônias é uma joia delicada que combina romantismo e sofisticação. Adicione essa peça especial à sua coleção e ilumine seu visual com um toque de brilho e elegância.', 70.77, 59.99, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7qy91gq05duc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F3281476