INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256173411', 'Tênis Olympikus Venus 3 Unissex Versátil Confortável Leve Resistente', 'Tênis Olympikus Venus 3 Unissex - A terceira edição do Olympikus Venus 3 é a escolha ideal para quem busca conforto e praticidade. Seu solado possui a tecnologia de amortecimento Evasense, que proporciona leveza e maior responsividade para as atividades diárias. O cabedal é confeccionado em tecido jacquard com arte gráfica e linhas orgânicas, trazendo um visual de movimento que combina resistência e versatilidade. Conta também com detalhes em laminado que levam a tecnologia High Frequency. Lingueta em confortável combinação de tecido dupla frontura + espuma. Seu atacador é composto por tecido poliéster texturizado e o forro em poliéster com espuma. Além disso, conta com puxador traseiro em fita para facilitar o calce e palmilha anatômica composta por poliéster e EVA, com aplicação gráfica. Características Gerais do Produto: • Gênero: Unissex • Marca: Olympikus Garantia: • 7 dias de garantia', 179.9, 179.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824gg-mpo3ditlrv9r6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1172340783%2F58256173411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
