INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206870925', 'Jibbitz™ Pingente Arco-Íris Único', 'Os maravilhosos Jibbitz™ Charms são acessórios que você coloca nos seus Crocs. Eles são fáceis de colocar e retirar, para que você possa mudar seus estilo a qualquer momento. Adicione os encantos dos Jibbitz™ Charms aos seus Crocs para mostrar que seu estilo e criatividade são únicos! De personagens conhecidos a emojis populares. Tem algo a dizer? Diga! Se ama alienígenas e unicórnios? Mostre! Fácil de colocar e ser removido, combina com qualquer look, companhia perfeita com detalhes bem visíveis. Não é um brinquedo. Não se destina a crianças menores de 3 anos de idade. As imagens do produto podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 14.99, 14.99, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260e-mlrvw5mqv8qp23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F58206870925', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
