INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42681357967', 'Jogo de Brocas 3 Pontas Para Madeira e Derivados Com 5 Peças de 3mm a 8mm - Vonder Madeira Derivados', '🪵 Jogo de Brocas 3 Pontas para Madeira 5 Peças 3mm a 8mm Vonder 🔩 Precisão, praticidade e excelente acabamento para seus trabalhos em madeira! O Jogo de Brocas 3 Pontas Vonder foi desenvolvido para proporcionar perfurações precisas em madeiras e seus derivados. Com ponta de afiação especial, garante fácil centralização do furo, reduzindo desvios e proporcionando um acabamento mais limpo e profissional. Ideal para marceneiros, carpinteiros, montadores de móveis, profissionais da construção civil e também para uso doméstico. ✨ Diferenciais do Produto: ✅ Ponta com afiação especial para melhor centralização ✅ Perfuração precisa e acabamento limpo ✅ Ideal para madeira e derivados ✅ Fabricadas em aço carbono resistente ✅ Estojo plástico para organização e transporte ✅ Excelente custo-benefício 📦 Conteúdo da Embalagem: • 01 Broca 3,0 mm • 01 Broca 4,0 mm • 01 Broca 5,0 mm • 01 Broca 6,0 mm • 01 Broca 8,0 mm • 01 Estojo plástico organizador 📋 Especificações Técnicas: • Marca: Vonder • Referência: 5301003008 • Material: Aço carbono • Quantidade de peças: 5 • Diâmetros: 3 mm, 4 mm, 5 mm, 6 mm e 8 mm • Tipo: Brocas 3 pontas • Aplicação: Madeira e derivados 🔨 Indicado para: • Madeira maciça • MDF • MDP • Compensado • Aglomerado • Outros derivados de madeira 🚚 Produto novo e original 📦 Pronta entrega 🔒 Compra 100% segura IMPORTANTE: SUA SATISFAÇÃO GARANTIDA! ✔️ -----> Entrega assegurada pela Shopee com garantia', 19.99, 15.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820le-moyak1w19l3404', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F42681357967', NULL, NULL, '2026-07-