INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20378587402', 'Mangueira Conjunto Trançada Verde 20m com Bico Sunflex', 'A mangueira trançada Sunflex vai facilitar as tarefas do seu dia a dia! Conte com maior flexibilidade e agilidade para utilizá-la em seu jardim ou quintal. Inclui adaptador para para torneira de jardim e ponta com esguicho para facilitar o uso. Resistência contra cortes, quebra, ressecamento ou danos gerais pela ação do tempo.', 91.9, 91.9, NULL, 'Home & Living > Gardening > Irrigation Systems', 'https://cf.shopee.com.br/file/sg-11134201-7qvg1-lfqyerc9ojwba2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F20378587402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
