INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799307277', 'Expositor Vertical Philco 309 Litros Porta de Vidro Branco PRE319 – 127 Volts', 'Expositor Vertical Philco 309 Litros Porta de Vidro Branco PRE319 – 127 Volts Apresentamos o Expositor Philco, um equipamento de excelência para manter seus produtos resfriados com eficiência e estilo. Seu design moderno, com porta de vidro duplo, proporciona uma visão clara do interior, enquanto sua capacidade impressionante de 309 litros oferece amplo espaço para armazenamento. Com um sistema de refrigeração por compressor e controle de temperatura ajustável na parte interna, o Expositor Philco garante uma operação eficaz, mantendo uma temperatura interna entre 1°C e 10°C. Com quatro prateleiras aramadas de alturas reguláveis, iluminação interna em LED e pés niveladores ajustáveis, este expositor é altamente versátil e adapta-se facilmente às suas necessidades. O sistema de refrigeração por ventilação forçada evita o acúmulo de suor na parte interna do refrigerador, garantindo a qualidade e frescor dos seus produtos. Invista na excelência e confiabilidade do Expositor Philco para realçar a apresentação dos seus itens refrigerados. Imagens meramente ilustrativas.', 4329.0, 4329.0, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-820lh-mnwx87sq8utde5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F23799307277', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
