INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892412631', 'ÁGUA MINERAL COM GÁS MINALBA GERANDO FALCÕES 269ML', 'VOCÊ ESTÁ COMPRANDO: ÁGUA MINERAL COM GÁS MINALBA GERANDO FALCÕES 269ML ORIGEM: BRASIL SOBRE O PRODUTO: A Minalba fez uma parceria com a Gerando Falcões para desenvolver o projeto Fala na Lata. Juntas, as marcas desenvolveram uma edição especial da água mineral Minalba em lata, que terá todo o lucro revertido para a instituição. As versões com gás e sem gás das latas ganham estampas com duas obras criadas exclusivamente pelo artista Lilo Vianna (@lilo_viana). “Saber que nossos produtos estão servindo como plataforma para dar visibilidade à criatividade e talento de artistas como Lilo Viana faz do Fala na Lata um projeto que representa um marco na trajetória da empresa e que muito nos orgulha, afirma Aélio Silveira, Diretor Superintendente da Minalba Brasil. “Trabalhar com arte, em si, já é algo muito especial, eu me sinto um grande privilegiado por este fato. Poder juntar essa paixão com grupos e potências maiores dque eu, por causas e valores tão genuínos, é algo que vai além dos meus sonhos. A parceria com a Gerando Falcões tem mudado a minha vida. Coisas assim me fazem sonhar ainda mais, eu jamais poderia fazer isso sozinho. Eu me sinto muito grato, por todos esses parceiros e pela forma como me abraçaram, e por poder lutar por causas que todos nós acreditamos”, afirma o artista. Água com gás Minalba A água com gás Minalba é uma bebida rica em minerais muito importantes para o bom funcionamento do organismo. Coletada em fontes naturais e cristalinas, ela passa por um processo certificado de envasamento, mantendo a pureza e seu estado natural.', 18.63, 18.63, NULL, 'Food & Beverages > Beverages > Water', 'https://cf.shopee.com.br/file/sg-11134201-7rbms-lpb1w04vuu4u07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F23892412631', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18861796694', 'Filtro Ar Fiat Uno 90 A 2014 Tecfil', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação UNO 1.6 MPI 2P E 4P 1994 até 1996 UNO 1.6R MPI / 1.6R / 1.5R 1990 até 1994 UNO ATTRACTIVE 1.0 EVO FIRE FLEX 8V 5P 2015 UNO CITY / CITY 1.0 4P 2000 até 2001 UNO CSL 1.6 4P (ARGENTINO) 1990 até 1995 UNO ECONOMY 1.4 EVO FIRE FLEX 8V 4P 2014 UNO ECONOMY CELEB. 1.4 EVO F. FLEX 8V 4P 2014 UNO EVOLUTION 1.4 FIRE FLEX 8V 5P 2015 UNO SPORT.INTERLAGOS 1.4 EVO F.FLEX 8V 2014 UNO SPORTING 1.4 EVO FIRE FLEX 8V 4P 2014 até 2015 UNO SPORTING DUALOGIC 1.4 EVO FLEX 8V 4P 2015 UNO TURBO 1.4 I.E. 2P 1994 até 1996 UNO VIVACE 1.0 EVO FIRE FLEX 8V 3P 2014 até 2015 UNO VIVACE CELEB. 1.0 EVO F. FLEX 8V 3P 2014 até 2015 UNO VIVACE CELEB. 1.0 EVO F.FLEX 8V 5P 2014 até 2015 UNO VIVACE COLLEGE 1.0 EVO FIREFLEX 5P 2014 UNO VIVACE ITALIA 1.0 EVO F. FLEX 8V 5P 2015 UNO VIVACE/RUA 1.0 EVO FIRE FLEX 8V 5P 2014 até 2015 Conteúdo Da Embalagem 1 Filtro de Ar Observação Motor: 1.0 1.4 1.5 1.6 Tipo de Veículo para Carros Marca Especialista no segmento de Filtros Automotivos a Tecfil foi fundada em 1953, e atualmente é a maior fábrica de filtros da América Latina, além de ser a líder e maior referência do mercado no segmento de reposição automotiva. A empresa possui ainda todas as Certificações exigidas no mercado, o que lhe confere diferenciais de qualidade. O Produto O filtro de ar é de extrema importância, por que ele elimina as impurezas que existem no ar do carro, para a mistura ar/combustível gerar uma combustão perfeita. Se o seu filtro estiver sujo e velho seu carro não passa na inspeção veicular, sem contar que se você rodar com o filtro de ar sujo seu consumo de combustível vai ser bem mais alto Importante •Recomendamos que os produtos sejam instalados por profissionais especializados e não se responsabiliza pelo mal uso ou instalação indevida, causando a perda da garantia. • • Tempo de garantia: 3 Meses •Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 •Imagem meramente ilustrativa •Valor unitário EAN 7891342002042 Código do Fabricante ARL4147 Combustível Álcool Flex Gasolina >', 18.17, 18.17, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbmz-lltqhekeo9b765', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F18861796694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997608535', 'Macaco Hidráulico Tipo Garrafa 10 Toneladas Manual Rino', 'MACACO HIDRÁULICO TIPO GARRAFA 10 TONELADAS MANUAL RINO O macaco hidráulico manual tipo garrafa é preparado para elevar cargas com peso de até 10 toneladas, desenvolvido em material de alta qualidade e resistência. É uma ferramenta indispensável para elevação de cargas, veículos e outros equipamentos. Altura suficiente para instalar um suporte rígido sob a carga elevada e reparos. O macaco hidráulico tipo garrafa não foi projetado para cargas de apoio em longo prazo sobre o peso ou para movê-lo. Antes da elevação certificar-se de que a carga é distribuída uniformemente sobre a superfície do centro. A carga levantada peso não deve exceder o peso especificado pelo fabricante. Especificações Técnicas: Capacidade de carga: 10 toneladas Altura mínima de elevação: 200 mm Conteúdo da Embalagem: 01 macaco hidráulico *Objetos de decoração das fotos não estão inclusos. *As cores podem variar conforme monitor utilizado para a visualização do anúncio.', 240.52, 181.5, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Lift', 'https://cf.shopee.com.br/file/sg-11134201-7rcep-lqtckdkiic7n00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984366979%2F20997608535', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
