INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203527702', 'Vinho Cordero Con Piel de Lobo Malbec Argentino Tinto 750ml', 'O Cordero Con Piel de Lobo Malbec 2024 é um vinho argentino jovem, vibrante e fiel ao estilo moderno da uva Malbec. Produzido em Mendoza, destaca notas intensas de frutas vermelhas e negras, toque leve de especiarias e um perfil fresco e descomplicado. No paladar, apresenta corpo médio, taninos macios e boa acidez, resultando em um vinho equilibrado, agradável e muito fácil de beber. Ideal para o dia a dia, encontros informais e harmonizações versáteis.', 54.88, 45.99, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjltfztec7pf78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1640913654%2F58203527702', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
