INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43258179321', 'Livro de Colorir - Farm Friends - Capa Flexivel', 'Descrição: Desperte a criatividade das crianças com o divertido Livro de Colorir Farm Friends, repleto de ilustrações encantadoras do mundo rural. Com capa flexível e páginas fáceis de manusear, essa edição é ideal para entreter e desenvolver a coordenação motora e a concentração dos pequenos. As ilustrações de animais e cenários da fazenda proporcionam momentos de aprendizado e diversão para crianças de todas as idades. Garanta já este livro educativo e proporcione horas de imaginação e criatividade para o seu filho. Palavras-chave: livro de colorir, livro infantil, farm friends, livro para crianças, capa flexível, animais da fazenda, colorir e aprender, atividades infantis, livro educativo, presente infantil, livro de atividades, criatividade infantil, coordenação motora, diversão para crianças, livro lúdico, livro fazenda, livro com desenhos, livro colorir animais, presente criativo, pintura infantil, arte para crianças, livro interativo, aprendizado infantil, educação infantil, entretenimento infantil', 15.33, 15.33, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc21cip2oqzre4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F43258179321', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7182456172', 'O Sorriso Escondido de Deus - John Piper', 'Descrição O Sorriso Escondido de Deus, de John Piper, apresenta histórias inspiradoras de três grandes homens de fé: John Bunyan, William Cowper e David Brainerd. Em meio a sofrimento, perseguição, depressão e enfermidades, esses servos de Deus permaneceram firmes, encontrando alegria e propósito em Cristo. A obra mostra como a graça divina se manifesta nos momentos mais sombrios e como a perseverança em meio às tribulações pode resultar em frutos espirituais abundantes. É uma leitura edificante para quem busca compreender a beleza do evangelho no sofrimento e deseja fortalecer sua fé em tempos de provação. Ficha técnica Autor: John Piper Editora: Shedd Publicações Acabamento: Brochura Páginas: 280 Dimensões: 14 × 21 cm Peso: 0,340 kg Idioma: Português ISBN: 9788588315136 Palavras-chave John Piper, sofrimento cristão, fé e perseverança, biografias cristãs, espiritualidade, graça de Deus, Shedd Publicações', 53.44, 53.44, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/c81c8c584b5b4d35d86d3af559d9856c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F7182456172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
