INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17488434536', 'Pulseira feminina elo cartie coração estampado bolinhas', 'Pulseira feminina elo Cartier em Prata 925 com coração estampado de bolinhas. Joia delicada, moderna e perfeita para o dia a dia. Material: Prata 925 Peso: 1,80 gramas Comprimento: 19,50cm (com extensor) A Pulseira Feminina Elo Cartier com Coração Estampado em Prata 925 é uma joia delicada e moderna, perfeita para quem ama acessórios elegantes com um toque romântico. Seu design combina a clássica corrente elo Cartier com um lindo coração texturizado em acabamento estampado de bolinhas, trazendo charme e sofisticação para qualquer look. Leve e versátil, essa pulseira é ideal para usar sozinha ou combinada com outras peças em composições modernas e estilosas. A Pulseira Elo Cartier com Coração Estampado em Prata 925 é a escolha ideal para quem busca uma joia romântica, sofisticada e cheia de estilo para todas as ocasiões.', 155.0, 99.99, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/sg-11134201-7rd6c-lvkqdsz0q433e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F17488434536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
