INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094711362', 'Shiny Revitalizador Pneu Pretinho Vonixx 500ml', 'Renovador e Protetor de Pneus. Desenvolvido para renovar, proteger e proporcionar brilho intenso e duradouro aos pneus. Resistente à água, mantém o aspecto de brilho molhado por até 60 dias, com rendimento de 15 a 20 aplicações em carros pequenos. — Brilho intenso e duradouro. — Proteção total. — Resistente à água. — Até 60 dias de durabilidade. O acabamento perfeito para pneus impecáveis. Adquira já! »ATENÇÃO« APLICAR FORA DA LUZ SOLAR. NÃO UTILIZAR EM SUPERFÍCIES QUENTES. MANTENHA LONGE DE CRIANÇAS E ANIMAIS DOMÉSTICOS. Evite contato com pele, olhos e boca. MODO DE USO — Limpe bem a superfície antes da aplicação. — Aplique com aplicador de espuma até a completa revitalização. — Se necessário, repita a operação. Contém 1 unidade.', 110.0, 59.4, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Brighteners', 'https://cf.shopee.com.br/file/sg-11134201-821e9-mgr3a7uqg6q259', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537166216%2F22094711362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
