INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57154750620', 'Amassador Manual de Legumes e Batatas em Aço Inox com Cabo Confortável de Plástico Duhome', '**Amassador manual para batatas** Amassador manual para batatas e legumes, ideal para preparar purês e pratos com alimentos cozidos de forma simples e eficiente. Fabricado com parte funcional em aço inox, oferece resistência e durabilidade. O cabo em plástico possui formato ergonômico, proporcionando conforto durante o uso e facilitando o manuseio, mesmo em preparos mais densos. Perfeito para o dia a dia, o utensílio é leve, prático e fácil de limpar, sendo indispensável na rotina da cozinha doméstica ou profissional. Características: - Ideal para amassar batatas, mandioquinhas, abóboras e outros legumes cozidos - Parte em aço inox: resistente e de alta durabilidade - Cabo anatômico em plástico, confortável ao toque - Simples de usar, lavar e armazenar - Excelente para uso diário Medidas: - Comprimento: 24 cm - Largura: 8 cm Imagens e vídeos são meramente ilustrativos. A tonalidade da cor pode variar conforme o monitor.', 28.9, 21.9, NULL, 'Home & Living > Kitchenware > Graters, Peelers & Cutters', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjiiykx35ybn0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F57154750620', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
