INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098961426', 'Capa case capinha para iPhone Air - Crystal Slim Magsafe - NÃO AMARELA - Transparente - Gshield', 'LEIA ANTES DE COMPRAR Os fabricantes de smartphones e smartwatches possuem variações de tamanho para cada tipo de produto, geralmente as mudanças de dimensões são acompanhadas pelo tamanho em polegadas ou pelas palavras: PLUS, +, PRO, PLAY, LITE, SE, MM, entre outras, confira antes da compra se seu dispositivo é compatível com o produto anunciado e evite transtornos em sua compra. Qualquer dúvida utilize o campo de perguntas no final da página ou leia as avaliações de outros consumidores. A Capa Crystal Slim Magsafe da Gshield foi projetada para quem busca proteção eficiente sem comprometer a estética do smartphone. Com um design ultrafino e transparência impecável, ela valoriza os detalhes do aparelho, permitindo que sua cor e acabamento fiquem sempre em destaque. Ideal para quem quer manter a aparência original do dispositivo sem abrir mão da segurança no dia a dia. Diferente de capas comuns que perdem a transparência com o tempo, a Crystal Slim é fabricada com acrílico de alta qualidade e tecnologia antiamarelamento, garantindo que sua aparência cristalina permaneça intacta mesmo com uso contínuo e exposição à luz. Esse diferencial evita o desgaste precoce e mantém o visual do smartphone sempre impecável. Seu design ultrafino é um dos pontos fortes da Capa Crystal Slim. Extremamente leve e discreta, ela se ajusta perfeitamente ao aparelho sem adicionar volume desnecessário, proporcionando uma pegada confortável e preservando a ergonomia original do smartphone. Além disso, sua construção em material rígido oferece resistência contra impactos, arranhões e pequenos acidentes do dia a dia, protegendo seu dispositivo sem comprometer seu visual. Outro destaque da capa está na tecnologia MagSafe integrada, que cria um anel de ímãs na parte traseira do celular, estabelecendo uma conexão magnética perfeita com carregadores sem fio compatíveis. Isso significa que você nunca mais terá que se preocupar com a posição correta na base de carregamento, pois a Crystal Slim Magsafe garante que seu dispositivo se alinhe de maneira precisa a cada uso, proporcionando uma experiência de carregamento sem esforço. Se você procura uma capa que proteja sem esconder o design do seu aparelho, a Capa Crystal Slim Magsafe da Gshield é a escolha ideal. Transparência duradoura, design ultrafino e resistência na medida certa – tudo isso em um acessório que combina proteção e elegância de forma equilibrada. Garanta já a sua e mantenha seu smartphone protegido sem abrir mão da estética original! ESPECIFICAÇÕES Marca: Gshield Material: Acrílico Dimensões: Dimensões exatas do aparelho Cor: Transparente Proteção: Contra impactos e riscos Certificações: US Military COMPATIBILIDADE iPhone Air ITENS INCLUSOS 1x Capa protetora GARANTIA 3 meses de garantia contra defeitos de fabricação e garantia vitalícia contra amarelamento Com decorrer do uso a capa pode apresentar arranhões pelo contato diário com superfícies SEGURO Aconselhamos para uma proteção completa a compra dos planos de coberturas contra roubo, furto e danos da Gshield, conheça nossos planos', 120.97, 120.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-824hz-mf6poatwm0i265', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22098961426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41860695110', 'Tenis Infantil Menino Casual FreeStyle KLIN - Branco', 'Tênis Infantil Casual FreeStyle da marca Klin é a escolha ideal para meninos que precisam de praticidade, conforto e muito estilo no dia a dia. Com um design moderno na cor branca e detalhes em azul, esse modelo combina com tudo, desde looks casuais até o uniforme escolar. O fechamento duplo por velcro oferece mais autonomia para os pequenos, facilitando o calce e garantindo um ajuste seguro. Fabricado com materiais resistentes e de alta qualidade, o tênis proporciona conforto prolongado, solado antiderrapante e ótima respirabilidade. Ideal para acompanhar todas as aventuras com segurança e leveza. Principais características: Cor branca com detalhes em azul: visual moderno e versátil Fechamento duplo por velcro: mais praticidade e firmeza Solado emborrachado com ótima aderência Palmilha macia para máximo conforto Ideal para escola, passeios e brincadeiras Características Gerais do Produto: • Coleção: PV 2025 • Cor: Branco • Garantia: 30 dias', 239.9, 162.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg2mn4070v0g00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404144117%2F41860695110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55150934486', 'O Dia em que Hugo Perdeu sua Baleia | Uma Cativante História sobre Neurodivergência', 'Hugo perdeu sua baleia. Procurou embaixo da cama... nada. Na casa da vovó... nada. No supermercado... também nada! Será que ela foi nadar bem longe sem avisar? Com a ajuda da mamãe, Hugo enfrenta um dia cheio de emoções na busca para reencontrar sua amiga. Nesta sensível história, Rodrigo Bibo nos mostra que cada criança tem um jeito especial de sentir o mundo e que amor, paciência e compreensão podem deixar qualquer dia mais leve. 21x23cm 48 Páginas', 44.9, 40.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821eq-mgra7ikben7w29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F55150934486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
