INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398265955', 'Bíblia De Estudo Thomas Nelson | NVI | Leitura Perfeita | Couro Legítimo Marrom', 'Essa é uma bíblia de estudo baseada na teologia bíblica, ou seja, ao invés de trabalhar os tópicos teológicos de forma isolada, ela segue a linha da grande narrativa bíblica, mostrando como, de Gênesis a Apocalipse, Deus foi mostrando sua vontade para a humanidade, como as coisas se desenvolveram do Antigo para o Novo Testamento e como Deus se revelou de forma orgânica mediante as necessidades de seu povo. A Bíblia conta com: • Introduções explicativas; • Tradução NVI; • Mais de 60 gráficos e diagramas; • Milhares de referências bíblicas cruzadas (que nos mostram como Deus é imutável apesar de se revelar gradualmente); • Centenas de fotografias coloridas; • Mais de 90 mapas; • 28 artigos bíblico-teológicos; • Fonte Leitura Perfeita. 24x16 cm 2720 Páginas', 525.99, 525.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdvq-mcrv2fer2acmd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F21398265955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
