INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9856786813', 'Kit 3 Cuecas Boxer Algodão Cotton Preta C5', 'Cueca Boxer C5 é uma ótima cueca masculina de entrada (mais popular) Essas cuecas boxer são confeccionadas em algodão (Cotton) com elastano, tecido leve e macio, desenvolvido especialmente para quem não abre mão do conforto e busca preço. Modelagem boxer com formato anatômico que proporciona total aderência, e se adapta perfeitamente ao corpo. Composição: 95% Algodão 5% Elastano Tamanhos: P (36-38) M (40-42) G (44-46) GG (48-50) O Kit é enviado de forma sortida, podendo haver repetição de cores. A Compramais tem como missão desde 2013 proporcionar satisfação e qualidade para clientes em todo o Brasil. Trabalhamos com agilidade para garantir que seu pacote chegue com rapidez em suas mãos, no conforto do seu lar e sem precisar sair de casa! Temos um catálogo extenso de moda íntima que conta com itens femininos, masculinos e infantis. Ainda tem alguma dúvida? Nos faça uma pergunta! Compramais, paixão em moda íntima.', 52.9, 52.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/bb495127e2dbd4a7d92ae306969e681d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328687466%2F9856786813', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694500703', 'Massa Corrida Sherwin Williams 6Kg', 'SOBRE O PRODUTO SHERWIN WILLIAMS MASSA CORRIDA é utilizada para nivelar e corrigir pequenas imperfeições em paredes internas secas e tetos. Sua fórmula inovadora permite fácil aplicação através de diversas ferramentas como: Rolo, Airless e a clássica desempenadeira e melhora no lixamento. SHERWIN-WILLIAMS MASSA CORRIDA garante qualidade e economia para sua pintura. SOBRE A FABRICANTE A Sherwin Williams é referência global em tintas, guiada por valores como integridade, qualidade e inovação. Com mais de 64.000 colaboradores, destaca-se pelo compromisso com pessoas, comunidades e sustentabilidade. Reconhecida por excelência em produtos e serviços, fortalece continuamente sua liderança no mercado.', 33.9, 33.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-824h7-mfl8w6xqzax6ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F22694500703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44358613965', 'Kit Chuteira Infantil Costurada Futebol Campo Trava Light + Mochila + Meiao e Relogio', 'Domine o campo com nossas chuteiras infantis sintéticas de última geração! Projetadas especialmente para os pequenos jogadores, nossas chuteiras oferecem desempenho máximo em terrenos naturais, proporcionando um ajuste perfeito e durabilidade excepcional. Deixe seu filho brilhar em campo com agilidade e precisão, enquanto desfruta do conforto incomparável que só nossas chuteiras podem oferecer. Porque o futebol é mais do que marcar gols, é sobre a paixão em cada chute na bola. Por isso, seus filhos merecem calçados que acompanhem cada passo. Com as chuteiras Light, eles poderão aproveitar ao máximo suas habilidades e se divertir ao máximo no campo. Conteúdo do kit: 1 Par de chuteira campo infantil 1 Relógio digital infantil (cor sortida) 1 Mochila bag 1 Meião infantil (cor sortida) Características do Produto: - Estilo: Campo - Material exterior: Sintético - Material da sola: PVC - Tipo de ajuste: Cadarço Dicas para a Escolha do Tamanho: - A medida da numeração é baseada no tamanho aproximado da palmilha. Sempre compre com 0,5 cm de folga para maior segurança. - Evite problemas com trocas por tamanho, decida com atenção a numeração desejada seguindo a tabela abaixo! Tabela de Medidas: - 26 - 17,5 cm - 27 - 18,0 cm - 28 - 19,5 cm - 29 - 20,0 cm - 30 - 20,5 cm - 31 - 21,0 cm - 32 - 21,5 cm - 33 - 22,5 cm - 34 - 23,0 cm - 35 - 23,5 cm - 36 - 24,0 cm Instruções de Lavagem da Chuteira: - Não lavar os calçados em máquina de lavar roupas, usar apenas pano úmido. - A secagem deve ser realizada na sombra. Garantia contra defeitos de fabricação!', 79.99, 60.99, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/br-11134275-7r98o-mc85z7gasiqz38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908041635%2F44358613965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197470880', 'Torneira Cozinha De Parede Gourmet Misturador Quente E Frio Cromada Brilhante Yesop', 'Torneira Cozinha. Desenvolvido com matéria prima de alta qualidade, o Misturador Para Cozinha é a escolha perfeita para quem procura um modelo de excelência. Com dois comandos individuais, permite o controle da vazão de água e a mistura de água quente com fria. Resistente a riscos e corrosões. Além disso, possui um design moderno que a torna um elemento decorativo elegante, adicionando um toque de requinte e sofisticação à sua cozinha. DADOS TÉCNICOS: - Mecanismo cerâmico de ¼ de volta; - Suporta até 70º C de temperatura; - Possibilidade de uso com água de diferentes origens; - Bica Flexível; - Articulado.', 549.0, 269.0, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-820m2-mos18wkyglqd80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464586953%2F22197470880', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294389592', 'Bandeja Organizadora Banheiro Cristal 21cm Plástico Transparente Ideal Perfumes Cosméticos Arthi', 'A Bandeja Organizadora para Banheiro Cristal 21cm Natural - Arthi é a escolha ideal para quem busca organização, praticidade e beleza em cada detalhe do ambiente. Compacta e funcional, ela ajuda a manter cosméticos, acessórios, perfumes e itens de higiene pessoal sempre à mão, deixando o espaço mais limpo e harmonioso. Produzida pela tradicional Arthi, a bandeja é confeccionada em material plástico resistente e de alta durabilidade, garantindo longa vida útil e fácil manutenção. Com dimensões de 2cm de altura e 21cm de largura, é perfeita para bancadas de banheiro, lavabos, closets ou penteadeiras, mas também pode ser utilizada em outros ambientes da casa, como cozinhas, escritórios ou lavanderias. Seu design transparente e moderno, com acabamento cristal, oferece um visual leve e sofisticado, permitindo visualizar os objetos com facilidade e valorizando a decoração. A proposta modular permite combinar com outras bandejas da mesma linha, otimizando o espaço e criando uma organização personalizada conforme a sua necessidade. Além de prática, a Bandeja Modular Arthi adiciona um toque de elegância e funcionalidade à rotina, ajudando a transformar pequenos espaços em ambientes mais organizados, bonitos e acolhedores. Dica de uso: ideal para organizar perfumes, cremes, maquiagens, escovas e outros itens essenciais, mantendo tudo sempre visível e acessível.', 36.9, 26.2, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gb-me67ozjlspaea7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1081505086%2F22294389592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797685662', 'Tornozeleira Joelheira Munhequeira Cotoveleira Ortopedica Compressão Estabilizadora Elastica', '🏋️‍♂️ Tornozeleira Joelheira Munhequeira Cotoveleira Ortopedica Compressão Estabilizadora Elastica 🏃‍♀️ 🔝 Melhore sua Performance na Academia! 🔝 💪 Benefícios: Proteção e Aderência: Maior segurança na realização de exercícios, ideal para todas as práticas esportivas, desde academia até ciclismo. Tecido Leve e Respirável: Melhora a circulação e oxigenação do sangue, aumentando o desempenho muscular e acelerando a recuperação de lesões e articulações. Anti Odor: Tecido que absorve o suor, mantendo pés e braços secos e sem odor, evitando a coceira comum em suportes de neoprene. Uso contínuo por horas. 📦 Especificações: Produto: Tornozeleira Cotoveleira Munhequeira ou Joelheira Quantidade: 2 Unidade Tamanho: Único ajustável 🔹 Ideal para: Imobilização patelar Proteção articular Redução do desconforto Recuperação de lesões Alívio de dores Prevenção de lesões 🔹 Material: Tecido Spandex, que mantém a região aquecida e ajuda na circulação sanguínea. Alça elástica com acabamento reforçado para compressão ajustável e reforço lateral. 🎯 Aproveite para Adquirir os Dois Juntos e Maximizar seu Desempenho! 🎯 🔹 Garantia de Segurança e Conforto para seus Joelhos: Use na prática de exercícios, recuperação de lesões e reabilitação, aliviando incômodos e dores.', 39.9, 16.99, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Gym Protective Gears', 'https://cf.shopee.com.br/file/sg-11134201-7reqb-m2bdo4ybnyo3e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F22797685662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55403304724', 'Painel Completo Honda CG 125 Today / Titan 125 1992 A 1999', 'PAINEL COMPLETO TODAY/TITAN1992 A 1999 CONTEÚDO: 1 PAINEL COMPLETO APLICAÇÃO: TODAY / TITAN 1992 A 1999 GARANTIA CONTRA DEFEITO DE FABRICA POR 30 DIAS A instalação deve ser realizada por um profissional especializado. ✨ Por que escolher JDMSPEED? Produtos idênticos aos originais. Marca nacional localizada em São Paulo. Suporte total ao cliente antes e depois da compra. Envio rápido e seguro. 🛒 Compre Agora e Garanta a Performance do Seu Veículo! Peça de reposição de ALTA QUALIDADE, com padrão de fabricação JDMSPEED. Produto idêntico ao original, garantindo encaixe perfeito e durabilidade para o seu veículo. Somos a JDMSPEED: Sua marca de confiança em São Paulo. ⚠️ ATENÇÃO IMPORTANTE – ANTES DE COMPRAR: Para garantir a satisfação total e evitar transtornos com trocas, pedimos a gentileza de: CONFERIR BEM TODOS OS DETALHES da peça nas fotos e na ficha técnica do anúncio. Verificar a aplicação correta (modelo, ano e motor) compatível com o seu veículo. Recomendamos comparar o produto anunciado com a peça que já está instalada no seu carro. Em caso de incerteza, utilize o campo de perguntas! Oferecemos atendimento completo para a resolução de quaisquer dúvidas. 🔄 Política de Troca e Devolução (Condições Obrigatórias): Priorizamos a transparência e a qualidade. A devolução ou troca do produto será aceita SOMENTE mediante o cumprimento rigoroso das seguintes condições: O produto deve estar sem marcas de uso e em perfeito estado. Devolução com a Embalagem Original intacta. Obrigatório o envio da Nota Fiscal (DANFE). Com o Selo de Garantia da JDMSPEED intacto e visível. Defeito de Fabricação: Em caso de alegação de defeito, a peça será enviada para análise técnica antes de qualquer ressarcimento ou troca, conforme as normas do CDC. Como sei que o produto é compatível com meu carro? Verifique atentamente os carros listados na aplicação acima, confira a lista de códigos de referência e compare as fotos com o produto que tem em mãos. Deve ser instalado por um profissional? Sim, sempre recomendamos que a instalação seja feita por um profissional especializado, não nos responsabilizamos pelo mau uso ou instalação indevida, isso pode causar a perda da garantia. Garantia do vendedor: 90 dias.', 156.2, 78.1, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Panel and Speedometer', 'https://cf.shopee.com.br/file/sg-11134201-824gq-mprl09gpbxmo71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1550959167%2F55403304724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099347623', 'Bola Interativa Cachorro 8/10CM Brinquedo Divertido De Mastigar Wobble Wag Giggle Ball', 'Bola Interativa para Cachorro com Som Giggle – Brinquedo Mastigável e Divertido 🎾 DESCRIÇÃO A bola que faz barulho, provoca curiosidade e mantém o cachorro ocupado de verdade. Rola, balança e solta sons divertidos que estimulam o instinto natural de brincar. Cachorro entretido, dono em paz. Clássico que funciona — ontem, hoje e sempre. ✅ CARACTERÍSTICAS • Emite sons divertidos (giggle) ao rolar ou sacudir • Estimula atividade física e mental • Mantém o pet ativo, feliz e longe do tédio • 6 áreas de pegada, fácil para cães de qualquer porte • Ideal para brincadeiras internas e externas • Material resistente e flexível 📏 ESPECIFICAÇÕES • Tamanhos disponíveis: 8 x 8 cm ou 10 x 10 cm • Diâmetro: 150 mm • Peso: 330 g • Material: Vinil sem ftalato (seguro para pets) 📦 CONTEÚDO DA EMBALAGEM • 1x Bola Interativa Giggle para Cachorro Brinquedo bom é simples, resistente e diverte de verdade. O resto é firula. 🐕🎾', 150.0, 39.9, NULL, 'Pets > Pet Accessories > Toys', 'https://cf.shopee.com.br/file/sg-11134201-8261f-mkvx2r54l79g92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F23099347623', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698822891', 'Lanterna Portátil Dobravél de Trabalho de Reparo Pro e Lite com Ímã Led Multifuncional Bivolt', '🔦 Lanterna Portátil Dobrável de Trabalho Lite ou PRO com Ímã – LED Multifuncional USB Bivolt A lanterna ideal para trabalhos de reparo, acampamentos, emergências ou uso doméstico. Compacta, potente e dobrável, oferece iluminação direcionada e prática para qualquer situação. ✅ Diferenciais Design Dobrável (9cm) e (25cm): ajuste o ângulo conforme a necessidade. Base Magnética: fixa facilmente em superfícies metálicas, deixando as mãos livres. Multifuncional: ideal para oficinas, manutenção automotiva, camping, pesca, uso residencial ou em situações de emergência. Recarregável via USB: praticidade e economia, sem necessidade de pilhas. Luz LED Forte e Eficiente: alta luminosidade com baixo consumo de energia. 📏 Especificações Técnicas Tipo: Lanterna Portátil Dobrável Fonte de Luz: LED Comprimento: 9cm (Versão Lite) Comprimento: 25cm (Versão PRO) Alimentação: Bateria recarregável USB Tensão: Bivolt Funções: iluminação frontal e lateral Material: ABS + liga metálica Base: Ímã super forte 📦 Itens Inclusos 1 a 3x Lanterna Portátil Dobrável de Trabalho LED 1 a 3x Cabo USB para carregamento ⚡ Versátil, prática e indispensável no dia a dia!', 40.0, 24.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdye-mdm2scvaz9hw36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F22698822891', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
