INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299559788', 'Conjunto 2 Cadeiras Rainha Nesher Madeira Maciça Mel Off White', 'O conjunto de 2 cadeiras Rainha da Nesher é a escolha perfeita para adicionar elegância e conforto à sua sala de jantar. Feitas em madeira maciça, essas cadeiras garantem durabilidade e resistência. Sua cor mel natural traz um toque de beleza e aconchego ao ambiente. Com estofamento em linho off white, proporcionam conforto durante as refeições. Além disso, o modelo clássico e sofisticado das cadeiras Rainha complementa diversos estilos de decoração. Renove sua sala de jantar com o conjunto de cadeiras Rainha da Nesher e desfrute de momentos memoráveis com estilo e conforto. Especificações: - Comprimento: 48 cm - Largura: 56 cm - Altura: 90 cm - Estrutura em madeira maciça eucalipto - Assento com espuma de alta densidade D40 - Detalhe do encosto em ratan - Feltro de proteção para os pés - Peso máximo suportado: 100 kg - Cor: Mel Natural/Linho Off White - As configurações do seu monitor ou dispositivo móvel podem afetar a tonalidade da cor do produto. Conferir na descrição. - Recomendação de Limpeza: Limpar com pano seco para retirar o pó. Não aplicar produtos abrasivos. - Produtos de Enfeite e Eletrônicos Não Estão Inclusos.', 1129.9, 1029.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7repn-m2r1szzhhux51d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F19299559788', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
