INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092981271', 'Máscara de Tratamento Pantene Pro-V Hidratação 270ml', 'LONG DESCRIPTION:Precisa de uma solução hidratante para os danos? A Máscara Capilar Hidratação Pantene é para você. Complete o seu cronograma capilar com a nova máscara de hidratação, ideal para cabelos secos ou ressecados.A nova fórmula Nutri-Pérolas Pro-V é uma infusão reparadora contra o dano*; contém Pérolas Pro-Vitaminas solúveis e Óleo de Coco, para Cabelos até 100% mais fortes e hidratados*. As Pérolas Pro-Vitaminas solúveis são partículas que liberam milhões de lipídios que se dissolvem no creme, uma tecnologia exclusiva Pantene. Sinta a diferença. *Dano ao brilho e a suavidade**vs shampoo sem ingredientes condicionadores depois de 4 usos.SHORT DESCRIPTION: Precisa de uma solução hidratante para os danos? A Máscara Capilar Hidratação Pantene é para você. Complete o seu cronograma capilar com a nova máscara de hidratação, ideal para cabelos secos ou ressecados. A nova fórmula Nutri-Pérolas Pro-V é uma infusão reparadora contra o dano*; contém Pérolas Pro-Vitaminas solúveis e Óleo de Coco, para Cabelos até 100% mais fortes e hidratados*.*Dano ao brilho e a suavidade**vs shampoo sem ingredientes condicionadores depois de 4 usos. Contém Pérolas Pro-Vitaminas solúveis e Óleo de Coco Para cabelos até 100% mais fortes e hidratados* Ideal para cabelos secos ou ressecados As Pérolas Pro-Vitaminas são partículas que liberam milhões de lipídios que se dissolvem no creme, uma tecnologia exclusiva Pantene Ideal para o seu cronograma capilar *vs shampoo sem ingredientes condicionadores depois de 4 usos', 34.89, 32.02, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd51-lukp6m3cq7rz4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1231988