INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494955347', 'Tênis Kolosh Esportivo Feminino Para Caminhada e Atividades ao Ar Livre ou Academia E0270', 'Produto marca Kolosh. O Tênis Kolosh Esportivo Feminino é a escolha perfeita para quem busca um calçado que combine minimalismo, conforto, estilo e sustentabilidade para o dia a dia. Feito em tecido que abraça o pé e traz um toque diferenciado, com peças em sintético em locais estratégicos, junto com a tecnologia Frequency, feito sem costuras, proporcionando um visual moderno. Leve, pesando 0,669 kg, ainda conta com a sola de 6,2 cm feita em E-tpu+ feita com efeito termoconformado, que traz leveza e absorção de impactos, com uma peça estabilizadora da pisada, que agrega no visual com seu detalhe vazado e garante maior conforto ao andar! Com cadarços reguláveis permitindo um perfeito ajuste no pé, juntamente da palmilha Impulse+ de memória inteligente, ainda mais leve e macia, feita com 2% de borracha recuperada em sua composição, tornando o andar confortável o dia todo! Além disso, é versátil e combina com diversos looks, desde um short jeans e camiseta para um visual casual até uma calça jogger e moletom para um estilo mais esportivo. o design minimalista e os detalhes modernos do tênis o tornam a peça perfeita para complementar qualquer look. Peso: 0,669 kg Altura da sola: 5,20 cm Altura do salto: 1,0 cm', 279.9, 179.9, NULL, 'Sports & Outdoors > Sports Footwear > Hiking Shoes', 'https://cf.shopee.com.br/file/sg-11134201-820od-mnkadgeee22r07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1776349571%2F22494955347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
