INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28182942660', 'Estojo PVC Fantasia Infantil Kids Escolar Material Escolar Papelaria Animais Estampado', 'O Estojo PVC Fantasia Infantil é perfeito para deixar o momento de estudar mais divertido e colorido. Com estampas alegres de animais e personagens encantadores, ele é ideal para a criançada que adora um toque de imaginação no material escolar. Feito em PVC resistente, é fácil de limpar, leve de carregar e oferece espaço ideal para organizar lápis, canetas, borrachas e outros itens de papelaria. Seu design infantil e divertido estimula a criatividade e torna a volta às aulas muito mais animada. Um estojo prático, durável e cheio de fantasia para acompanhar os pequenos em todas as aventuras escolares!', 23.9, 12.26, NULL, 'Stationery > School & Office Equipment > Pencil Cases', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8esznj9i9lda6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F28182942660', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
