INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15366249174', 'Quebrando a Rotina | Max Lucado', 'Você pode não ser o que desejar ser. Mas se quiser, poderá ser tudo o que Deus quer que você seja.Quebrando a Rotina traz princípios práticos para explorar sua personalidade e colocar as suas qualidades em ação. Através de um guia de estudo, Max Lucado mostra o caminho para encontrar e viver plenamente os planos de Deus, a fim de despertar uma força poderosa dentro de você e encontrar uma posição confortável nos planos do Pai. 256 Páginas 15x22cm', 41.9, 40.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/73391053c16397c579ebaf0f9dc56935', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F15366249174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097667153', 'Rotor Distribuidor Vw Santana 1993 a 2006 - 106521 - 21300', 'Rotor Distribuidor Vw Santana 1993 a 2006 106521 21300 TODOS (IGNIÇÃO ELETRÔNICA/TZH - PONTA MAIOR) O rotor é um dispositivo do sistema de ignição que tem por finalidade, distribuir as centelhas de alta tensão para cada um dos pólos da tampa do distribuidor. Alguns rotores possuem uma resistência entre seu contato central e sua extremidade. Essa resistência serve para atenuar as interferências eletromagnéticas provocadas pela alta tensão do sistema.', 42.93, 42.93, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rd40-lufeivnfitqf91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21097667153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798005570', 'Tensor Correia Alternador KA 2001/2007 - 45739 - VT8134', 'Tensor Correia Alternador KA 2001/2007 Motor 1.6 8v - (72 x 52,8 x 25) Tensor correia alternador: Aplica-se na parte de fora do motor. Sua função é aplicar carga/pressão constante na correia, com a finalidade de evitar que a mesma se solte do sistema de polias, compensar eventuais folgas ou tensões excessivas que possam prejudicar o sincronismo do motor e o funcionamento dos acessórios do veículo.', 173.58, 173.58, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbk1-lmqjpzs1jo40e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22798005570', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493522537', 'Reparo Bico Injetor Peugeot 207 2008 a 2014 - 187867 - 1249', 'Reparo Bico Injetor Peugeot 207 2008 a 2014 187867 1249 1.4 8v /1.6 16v Flex - (Multi Point) (Sistema Bosch/Rochester) (4 Ponteiras + 4 Filtros + 8 O''rings) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 43.02, 43.02, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/br-11134201-820m7-mqxu7u653cp2b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23493522537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40759002757', 'Cortador Repolho Inox Multifuncional Fatiador Legumes Verduras Manual Cozinha Profissional', 'O fatiador foi desenvolvido pensando em facilitar o dia a dia de todos que buscam agilidade e praticidade no preparo dos alimentos saudáveis. Nosso produto está entre os melhores Fatiadores do mercado, devido ao seu material injetado em ABS, com lâmina em aço. O multifuncional que fatia e descasca de forma rápida e uniforme, qualquer tipo de legume e verduras em geral. Procurando solucionar aos agentes de cozinha uma qualidade superior na preparação dos melhores cardápios. A retirada dos núcleos do alface e do repolho é possível aumentar o seu tempo de geladeira. Ideal para retirar miolos de repolhos e alfaces! Modo de uso: -Faça um corte rápido ao redor do nucleo e o contorne -Levante o miolo do repolho e retire-o Com a retirada do miolo de repolhos e alfaces introduza um papel úmido no local e coloque o repolho em um saco plástico assim durando muito tempo sem estragar na geladeira.', 22.49, 9.41, NULL, 'Home & Living > Kitchenware > Graters, Peelers & Cutters', 'https://cf.shopee.com.br/file/br-11134207-820ln-mnwvm1x7yznkd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F40759002757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
