INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398923373', 'Combo Completo Casa e Lavanderia Vinagreen', 'O Kit Completo Vinagreen é a solução perfeita para você! Ele reúne todos os itens essenciais para deixar sua casa impecável, da lavanderia à cozinha. Com fórmulas concentradas e fragrâncias incríveis, você garante economia, praticidade e um cuidado especial com cada cantinho. Descubra a fragrância relaxante da Lavanda, a suavidade do Algodão e a frescura tropical do Coco, perfumando suas roupas e ambientes. Cada produto foi pensado para oferecer resultados excelentes, com o bônus de aromas que trazem uma sensação de bem-estar. Tenha em mãos uma seleção completa de produtos para a limpeza e cuidado de sua casa. O Kit Essencial Vinagreen foi montado com os itens mais procurados da linha, garantindo eficiência, qualidade e economia. 1 Amaciante Concentrado 1L (Lavanda) 1 Amaciante Concentrado 1L (Algodão) 1 Amaciante Concentrado 1L (Coco) 1 Multiuso 500ml (Lavanda) 1 Multiuso 500ml (Natural) 1 Alvejante Vinagreen 1 Lava Roupas Tradicional 3L (Lavanda) 1 Lava Roupas 3L (Coco) 1 Passa Fácil Vinagreen 1 Detergente Vinagreen 1 Desengordurante Vinagreen', 283.51, 233.89, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meyiv733s4cl0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583886098%2F23398923373', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
