INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4583358078', 'Liderando Como Jesus - Larry Titus', '📝 Descrição: Liderando Como Jesus, de Larry Titus, apresenta uma abordagem transformadora sobre liderança baseada no exemplo de Cristo. Com linguagem acessível e profunda sabedoria bíblica, o autor mostra que liderar não é sobre status ou poder, mas sobre servir com humildade, amor e propósito. Ideal para líderes cristãos, pastores, empreendedores e todos que desejam exercer influência com integridade, este livro oferece princípios práticos para impactar vidas e construir legados duradouros. 📄 Ficha técnica: Título: Liderando Como Jesus – Princípios de Sucesso do Maior Líder de Todos os Tempos Autor: Larry Titus Editora: Thomas Nelson Brasil Ano de publicação: 2019 ISBN: 9788571670327 Idioma: Português Número de páginas: 304 Formato: Brochura Dimensões: 23 cm x 16 cm Peso: 457 g Categoria: Liderança cristã, vida cristã, desenvolvimento pessoal Indicação etária: A partir de 16 anos 🔍 Palavras-chave: liderando como jesus, larry titus, liderança cristã, liderança com propósito, thomas nelson brasil, espírito de servo, influência com integridade, livro sobre liderança, exemplo de cristo, desenvolvimento espiritual', 48.57, 48.57, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgc88hn51ibp8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F4583358078', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
