INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199345299', 'Bolsa Para Ferramentas de Nylon Mini Soft Case Bosch Azul', 'Características: - Material de Nylon Durável: A bolsa é feita de nylon resistente, o que a torna durável e capaz de resistir ao desgaste durante o uso. - Design Compacto: Sendo uma "Mini Soft Case," essa bolsa tem um design compacto que a torna ideal para armazenar ferramentas e acessórios de tamanho menor. - Zíper Durável: A bolsa possui um zíper durável que facilita o acesso ao seu conteúdo. - Alça de Transporte: Vem com uma alça de transporte que permite transportar a bolsa com facilidade, seja para o local de trabalho ou para armazenamento. - Versatilidade de Uso: Essas bolsas são versáteis e podem ser usadas para armazenar uma variedade de ferramentas, acessórios e itens pequenos.', 72.0, 72.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjssup0i2akh6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F22199345299', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
