INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099557567', 'Cavaquinho Giannini Elétrico Cs-14 Ep Bk + Capa E Acessórios', 'ACOMPANHA O KIT: 1) CAVACO CS14-EP-BK 2) CAPA REFORÇADA 3) AFINADOR 4) 3 PALHETAS O Cavaco Elétrico Giannini CS14 EP Passivo com Equalizador Cor BK - Preto é um instrumento de alta qualidade, projetado para músicos que buscam um som excepcional e uma aparência elegante. Com um corpo feito de Linden, este cavaquinho oferece uma sonoridade rica e vibrante, ideal para qualquer estilo musical. A marca Giannini é conhecida pela sua tradição e excelência na fabricação de instrumentos musicais, e este cavaquinho não é exceção. O modelo CS-14 possui um braço de Maple, que proporciona uma tocabilidade confortável e uma resposta rápida, permitindo que você execute suas músicas com facilidade e precisão. Este cavaquinho acústico vem com cordas de aço, que produzem um som brilhante e claro, com uma ótima projeção. Além disso, o equalizador embutido permite que você ajuste o som ao seu gosto, garantindo que suas performances sejam sempre do mais alto nível. Finalmente, a cor BK - Preto dá a este cavaquinho um visual sofisticado e moderno. Seja você um músico profissional ou um entusiasta da música, o Cavaco Elétrico Giannini CS14 EP Passivo com Equalizador Cor BK - Preto é uma escolha perfeita para elevar suas performances a um novo patamar.', 609.4, 609.4, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-820lv-mnu1vlryy3gg0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F19099557567', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9487385013', 'Encordoamento Violao Aco Strinberg Ws10 Extra Light 0.010 010', 'Somos a Eletromusic Loja Especializada a mais de 10 anos no Mercado. Qual é o nosso diferencial? Buscamos sempre oferecer qualidade com excelência por isso todos os nossos produtos são de Fornecedores Nacionais com rigoroso controle de qualidade, possuem nota fiscal eletrônica e garantia de fabrica. Você é bem vindo para fazer parte da nossa história. - O jogo de cordas de aço da WS10 Strinberg, é uma ótima dica para quem busca por um encordoamento profissional. A sua sonoridade permite ótimo brilho nos sons agudos e graves definidos, encordoamento leve excelente para quem quer tocar com mais conforto sem forçar tanto os dedos. Sua durabilidade é ótima quando comparada ao seu custo benefício. Dados Técnicos - Encordoamento Completo com 06 cordas para violão aço. - Marca: Strinberg - Calibre 010 Extra Light Material: Bronze - 1.e: 0,010" - 2.B: 0,014" - 3.G: w0,022" - 4.D: w0,030" - 5.A: w0,036" - 6.E: w0,047" Esse jogo de cordas é perfeito para violões do modelo Folk e Classico. Seja bem vindo e boas compras! Qualquer duvida, estamos a total disposição, basta fazer uma pergunta!', 29.0, 29.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbf8wqg8ct4o89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F9487385013', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
