INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22796831011', 'Touca De Natação Adulto Life Saver Cap 528875 Speedo', 'Proteja seu cabelo do cloro durante a natação com a touca Speedo LIFE SAVER Cap. Feita em silicone maleável e projetada para caber confortavelmente na cabeça, sem prender ou puxar os cabelos. Fácil e rápida de colocar. DETALHES : Modelo Life Saver Estampa exclusiva Maior proteção contra a água clorada Não agarra ou puxa os cabelos Fácil e rápida de colocar Proteje os cabelos contra as ações químicas da água Produto 100% Silicone macio, excelente para pessoas com pele sensível Alta resistência PRODUTO IMPORTADO DICAS DE USO : Evite contato com objetos pontiagudos Ao colocar ou retirar a touca, utilize as pontas dos dedos, nunca as unhas Não cortar o produto Após o uso, lave em água fria e limpa Enxugue interna e externamente com um pano seco e limpo Produto com prazo de validade indeterminado Garantia de 90 dias para defeitos de fabricação, e excluindo-se em caso de uso inadequado Itens inclusos: 01 un. Touca de Natação Adulto Life Saver Cap 528875 Speedo Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 47.52, 47.52, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/sg-11134201-7rbld-llb2wbqqtxyt0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F22796831011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42881456589', 'Fones de ouvido para dormir TWS X55, fones de ouvido Bluetooth sem fio, som estéreo Hi-Fi, com microfone, redução de', 'Característica: -Fone de ouvido para dormir. Muito confortável de usar -Controle com um botão -Microfone integrado -Display LED -Qualidade de som hi-fi, super alto -Bateria do fone de ouvido: 35mAh -Bateria da caixa de carregamento: 350mAh -Voltagem: 5V=1A Como emparelhar: Siga as etapas abaixo para emparelhar corretamente o fone de ouvido com seu dispositivo. 1. Verifique se o fone de ouvido está carregado. Se não estiver, carregue-o. 2. Retire os dois fones de ouvido da caixa de carregamento. [Retire-os ao mesmo tempo. Muito importante. O lado esquerdo e direito se emparelharão entre si.] 3. Aguarde 5 segundos. [Muito importante, pois os fones de ouvido esquerdo e direito estão se emparelhando.] 4. Habilite a função "Bluetooth" do seu dispositivo. 5. Encontre o ícone "TWS" na lista de dispositivos Bluetooth e clique em "TWS" para emparelhar. 6. "TWS" aparece na lista de emparelhados. A conexão foi bem-sucedida.', 26.0, 14.04, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134201-823q1-mp7wwrah5x4x3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F42881456589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
