INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299157212', 'Kit Explosão de Azeite de Oliva | bn.Cachos', 'Linha Explosão de Azeite de Oliva – bn.Cachos Cabelos secos e com frizz nunca mais! A bn.Cachos desenvolveu uma linha completa com o poder do Azeite de Oliva, ingrediente rico em lipídeos e vitamina E, que repara, nutre profundamente e combate o ressecamento dos fios. Todos os produtos são veganos e liberados, ideais para devolver maciez, brilho e definição natural aos cabelos. Conheça os produtos da linha: Shampoo Explosão de Azeite de Oliva Promove uma limpeza equilibrada que respeita a saúde do cabelo. Remove as impurezas sem ressecar e prepara os fios para receber os próximos cuidados. Condicionador Explosão de Azeite de Oliva Nutre profundamente, sela as cutículas, reduz a porosidade e devolve o brilho natural dos fios. Creme de Pentear Explosão de Azeite de Oliva Ajuda a repor a oleosidade natural do cabelo perdida diariamente. Sua fórmula garante umectação ao cabelo, recupera a nutrição e devolve as vitaminas essenciais para a saúde dos fios. Tratamento Explosão de Azeite de Oliva Hidrata e nutre intensamente, retém a umidade, combate a aspereza e o frizz, deixando os cabelos alinhados e protegidos. Resultado: cabelos nutridos, livres do ressecamento, com menos frizz, mais brilho e definição natural.', 157.99, 102.89, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/br-11134207-820lp-mldj1weflkw6b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F23299157212', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40182906293', 'SENBENBAO X55 PRO: Fones de ouvido à prova d’água IPX5, HiFi estéreo, com cancelamento de ruído e controle por toque', 'Tipo de bateria: bateria de lítio polimérica Bateria do fone: 30mAh Bateria do estojo de carregamento: 200mAh Tipos de carregamento: Fones – por contato magnético; Estojo – Tipo-C Tempo de carregamento dos fones: ~40 min Tempo de carregamento do estojo: ~1,5 h Tempo de reprodução: ~3–4 h por carga Recargas do estojo: ~3 ciclos Idioma do firmware: inglês neutro Materiais: ABS + PC Cores: preto / branco / verde / roxo Conteúdo da caixa: 2* fones de ouvido, 1* estojo de carregamento, 1* cordão Controles dos botões dos fones: • Toque único: Atender/encerrar chamada • Toque duplo: Avançar/retroceder faixa • Pressão longa (2s): Ativar assistente de voz • Toque triplo: Aumentar/diminuir volume • Pressão longa (5s): Ligar/desligar', 34.0, 34.0, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134253-82585-mqxv0yseo3ycbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F40182906293', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44614676608', 'Fone de Ouvido Gamer Sem Fio Bluetooth 5.4 Lenovo, Som Surround 8.0, Drivers de 40mm, Latência Baixa, Over-Ear, com', 'Fones de Ouvido Gaming Lenovo Esports | Vença Cada Jogo com Som Perfeito Cansado de perder partidas por não ouvir os passos inimigos? Irritado com fones que apertam sua cabeça após duas horas? Os fones de ouvido gaming Lenovo resolvem tudo isso—confiados por milhares de jogadores no mundo todo. • Som Surround 8.0 + Posicionamento Preciso: Drivers de 40 mm de frequência completa, padrão esports, proporcionam graves potentes e agudos nítidos. Áudio espacial dinâmico 720° quebra os limites do estéreo—você ouve cada passo, recarga e tiro vindo de todas as direções. Ganhe uma grande vantagem em FPS, MOBA e jogos de battle royale. • Modo Gaming Ultra-Baixo Latência: Latência ultrabaixa líder de mercado para sincronia perfeita de áudio e vídeo. Chega de frustração com “o som vem depois da ação”. Ative o modo de jogo com um toque; luz ambiente de respiração suave valoriza ainda mais seu setup. • 6 Microfones HD com Cancelamento de Ruído: Matriz de 6 microfones avançada com ENC inteligente bloqueia cliques de teclado, ventiladores e conversas de ambiente. Seus colegas ouvem você alto e claro mesmo em ambientes barulhentos—ideal para bate-papos por voz, reuniões e chamadas de vídeo. • Bateria para 35 Horas de Jogo Sem Parar: Até 35 horas de uso contínuo. Chip Bluetooth de alta eficiência mantém o consumo baixo. Ganhe um cabo 3,5 mm grátis—troque para o modo com fio instantaneamente quando necessário; nunca interrompa seu jogo. • Leve e Confortável para a Pele: Design ergonômico com almofadas de espuma de memória macia e arco ajustável. Serve em todos os tamanhos; material respirável evita suor—mesmo após 8+ horas. • Conexão em Modo Duplo: Bluetooth sem fio + 3,5 mm com fio. Alterne facilmente; compatível com PC, notebook, celular, tablet, PS4/5, Xbox. Sem drivers; conexão estável sem quedas. • Cores Disponíveis: Preto Clássico (discreto, versátil) e Edição Bege Premium (elegante, Bluetooth 6.0 atualizado). Perfeito para jogos competitivos, música, filmes, trabalho, estudo e viagens.', 116.0, 115.5, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134253-8258y-mqy2tg8a7jeta9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F44614676608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
